insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '0.1', 'Who this is written for', '0. HOW TO USE THIS DOCUMENT', 'This document is written for a language model that will be answering student questions about the IB Diploma Programme. It is not a student handout. It is a reference. It assumes the reader will retrieve sections rather than read linearly, so key facts are repeated across sections where a student is likely to arrive from different directions.

It is designed to let the system answer questions of these shapes:

- What exactly does this criterion reward?
- What loses marks here?
- What does this command term require?
- What are the common examiner complaints in this component?
- How do I move this piece of work from a 5 to a 7?
- What are the rules for this IA?
- Could this affect my diploma?
- What should I prioritise if I have limited time?', '', false, 0);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '0.2', 'The labelling convention (critical)', '0. HOW TO USE THIS DOCUMENT', 'Every substantive claim in this document carries one of four labels. **The system must preserve this distinction when answering students.** Confusing an official rule with a strategic opinion is the single most damaging failure mode for an IB assistant, because students act on rules.

| Label | Meaning | How the system should present it |
| --- | --- | --- |
| **[OFFICIAL]** | Stated in a current IB publication (regulations, assessment procedures, subject guide, policy document). | State plainly as a rule. |
| **[DERIVED]** | Follows logically and necessarily from official rules, or is arithmetic performed on official figures. | State as a consequence, showing the reasoning. |
| **[STRATEGY]** | Interpretation, pattern, or tactical advice from experienced teachers, examiners and students. Not an IB rule. | Frame explicitly as advice or observation, not policy. |
| **[UNCERTAIN]** | Widely reported but not verified against a primary source, or known to vary by school or session. | Flag the uncertainty and tell the student to confirm with their coordinator. |', 'label official derived strategy uncertain confidence trust', false, 1);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '0.3', 'Hard rules for the system', '0. HOW TO USE THIS DOCUMENT', '1. **Never invent an IB rule.** If the answer is not in this document, say so and direct the student to their DP coordinator or the subject guide. A confident wrong answer about a submission deadline or a word limit can cost a student a grade.
2. **Always establish the session and the guide before answering a subject question.** IB subjects are on rolling review cycles. The correct answer for a May 2026 candidate is often wrong for a May 2027 candidate. Section 2 is the map.
3. **Never reproduce IB assessment criteria verbatim.** IB rubrics are copyrighted. Paraphrase what a criterion rewards. Everything in this document is already paraphrased for that reason.
4. **The school is the intermediary.** [OFFICIAL] Students and parents must use the school''s DP coordinator for communication with the IB. Students cannot register themselves, request a remark, apply for access arrangements, or appeal directly. Any answer that tells a student to contact the IB directly is wrong. (Source: General regulations: Diploma Programme, articles 3.1, 10.1, 12.1, 17.4, published within *Diploma Programme Assessment procedures 2026*.)
5. **Distinguish "will lose marks" from "cannot be marked".** Several IB limits are not penalties. They are cut-offs. Exceeding a word count usually means the examiner stops reading, which is worse than a penalty because it silently removes the student''s best material.
6. **Never help a student cheat.** Section 5 defines what constitutes academic misconduct with unusual precision. The system''s role is to help students understand the assessment system and produce their own work better, never to produce assessed work for them, and never to help them evade authentication.', '', true, 2);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '0.4', 'What this document deliberately excludes', '0. HOW TO USE THIS DOCUMENT', 'Cheating, plagiarism, contract work, fabrication of data, evasion of authentication, sharing live exam content, and any other academic integrity violation. Section 10 ("legitimate strategies") is bounded by Section 5 ("academic integrity"). Where a strategy sits close to a line, the line is stated.

---', '', false, 3);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '1', 'CURRENCY MAP: WHICH GUIDE APPLIES TO WHICH STUDENT', null, 'This is the first thing to establish before answering almost any subject-specific question.', '', false, 4);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '1.1', 'How IB curriculum review works', '1. CURRENCY MAP: WHICH GUIDE APPLIES TO WHICH STUDENT', '[OFFICIAL] The IB reviews every subject on a cycle. A new guide is published roughly a year before first teaching, taught for two years, and then assessed for the first time. The published pattern is: guide launch (February of year X), first teaching (August of year X), first assessment (May of year X+2). (Source: ibo.org, "Read curriculum updates", last updated 24 March 2026.)

[DERIVED] This means at any moment there are students sitting under a guide that is already superseded for younger cohorts, and students being taught under a guide that has never been examined. Both need different answers. Advice built on past papers is often invalid for the first cohort of a new guide, because past papers for that model do not exist.', '', false, 5);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '1.2', 'First assessment table', '1. CURRENCY MAP: WHICH GUIDE APPLIES TO WHICH STUDENT', 'Verified against ibo.org curriculum updates page, 24 March 2026.

| Subject / component | First teaching | **First assessment** | Notes |
| --- | --- | --- | --- |
| Business management | Aug 2022 | **May 2024** | IA unified across SL and HL |
| Environmental systems and societies (ESS) | Aug 2024 | **May 2026** | ESS becomes available at HL for the first time |
| Global politics | Aug 2024 | **May 2026** | |
| Sports, exercise and health science | Aug 2024 | **May 2026** | |
| Biology, Chemistry, Physics | Aug 2023 | **May 2025** | Common "scientific investigation" IA |
| Psychology | Aug 2025 | **May 2027** | New concepts/content/contexts framework; new IA |
| Computer science | Aug 2025 | **May 2027** | Paper 3 removed; 35-hour IA |
| Design technology | Aug 2025 | **May 2027** | Paper 3 removed; 50-hour design project |
| Visual arts | Aug 2025 | **May 2027** | |
| **Extended essay** | Aug 2025 | **May 2027** | 34 marks becomes 30 marks; new pathways |
| CP core components | Aug 2025 | **May 2027** | |
| History | Aug 2026 | **May 2028** | Paired case studies replace prescribed subjects |
| Dance | Aug 2027 | **May 2029** | |
| Language ab initio | Aug 2027 | **May 2029** | |
| Language B | Aug 2027 | **May 2029** | |
| Religion and society | Aug 2027 | **May 2029** | |
| Mathematics: analysis and approaches | Aug 2027 | **May 2029** | IA remains the exploration; SL and HL criteria unified |
| Mathematics: applications and interpretation | Aug 2027 | **May 2029** | Same |

**Currently stable (no imminent change announced as of this compilation):** Language A: literature and Language A: language and literature (current guide, first assessment 2021), TOK (first assessment 2022), Economics (first assessment 2022), Geography, Philosophy, Digital society, Social and cultural anthropology, World religions, Music, Theatre, Film, Literature and performance.

[UNCERTAIN] CAS has no announced review date. Treat the current CAS guide as live.', 'which guide syllabus year session first assessment 2025 2026 2027 current', false, 6);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '1.3', 'Common currency traps', '1. CURRENCY MAP: WHICH GUIDE APPLIES TO WHICH STUDENT', '[STRATEGY] These produce most of the wrong answers found in student-facing IB content online:

- **Mathematics.** Widely reported in 2025 and 2026 that the new maths guide is "first assessment 2027". It is not. First teaching is August 2027 and first assessment is May 2029. Anyone sitting maths in 2027 or 2028 is on the 2021 guide.
- **Maths IA criterion names.** The pre-2021 guide called Criterion A "Communication" and Criterion B "Mathematical presentation". The current guide reverses this: A is Presentation, B is Mathematical communication. A lot of circulating advice uses the old labels.
- **Sciences.** The old three-paper model with options and a Personal Engagement IA criterion ended with the November 2024 session. Any advice mentioning "Options" or "Personal engagement" in Biology, Chemistry or Physics is dead.
- **ESS.** Old ESS was SL only, 2,250-word IA. New ESS is SL and HL, 3,000-word IA, with a new strategy criterion.
- **Business management.** The old model had different SL and HL IAs (SL 1,500 words, HL research proposal plus report, nine criteria). From May 2024 there is one common IA of 1,800 words marked out of 25.
- **TOK.** The presentation was replaced by the exhibition with first assessment 2022. Any advice mentioning a "real-life situation" (RLS) or a presentation is obsolete.
- **Extended essay.** The World Studies category is gone from May 2027, replaced by the interdisciplinary pathway. The 34-mark criteria and the three-entry RPPF apply only up to November 2026.', 'wrong guide outdated old syllabus changed', false, 7);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '1.4', 'On-screen examinations', '1. CURRENCY MAP: WHICH GUIDE APPLIES TO WHICH STUDENT', '[OFFICIAL] The IB began delivering some DP examinations on screen from the May 2026 session, starting with studies in language and literature and language acquisition subjects, with paper and on-screen running in parallel during the transition. All IB World Schools can opt in for those subject groups from November 2026. Further subject groups follow in phases, with a stated ambition of full transition by the early 2030s. (Sources: ibo.org announcements; AACRAO summary, 2025; multiple coordinator briefings, 2026.)

[OFFICIAL] The IB has stated that on-screen and paper versions carry the same questions, structure and standards, and that grade boundaries are set so that the format does not advantage either group.

[STRATEGY] The practical consequence for a student is exam technique, not content. Typing speed under pressure, on-screen annotation habits, and one specific known hazard: in on-screen papers, using the highlighter inside a multiple-choice question can change the selected answer. Students should re-check their selection after highlighting.

---', '', false, 8);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '2.1', 'Structure', '2. THE PROGRAMME AT A GLANCE', '[OFFICIAL] The IB Diploma Programme is a two-year, pre-university course for students roughly aged 16 to 19. A diploma candidate takes six subjects plus the three core components. (Source: General regulations, article 8; *Extended essay guide, first assessment 2027*, introduction.)

**The six groups:**

1. Studies in language and literature (Language A: literature; Language A: language and literature; Literature and performance)
2. Language acquisition (Language B; Language ab initio, SL only; Classical languages)
3. Individuals and societies (History, Economics, Geography, Psychology, Business management, Global politics, Philosophy, Digital society, Social and cultural anthropology, World religions SL, ESS)
4. Sciences (Biology, Chemistry, Physics, Computer science, Design technology, Sports exercise and health science, ESS)
5. Mathematics (Analysis and approaches; Applications and interpretation)
6. The arts (Visual arts, Music, Theatre, Dance, Film)

**Selection rules:**

[OFFICIAL] One subject from each of groups 1 to 5. The sixth subject is either from group 6, or a second subject drawn from groups 1 to 4. Normally three subjects are taken at HL and not more than four; the remainder at SL. Recommended teaching hours are 240 for HL and 150 for SL. (Source: *Extended essay guide, first assessment 2027*, "Choosing the right combination".)

[OFFICIAL] Environmental systems and societies is a cross-disciplinary subject that can satisfy either the group 3 or the group 4 requirement, but not both simultaneously.

[OFFICIAL] All HL subjects, the core, and at least one SL subject must be taught across the full two years. Up to two SL subjects may be taught in the first year only and assessed at the end of it, as **anticipated subjects**. Language ab initio and pilot subjects must always run the full two years. (Source: General regulations, article 8.)

[OFFICIAL] Response language: in groups 1 and 2, all assessment must be in the target language. In groups 3, 4, 5, 6 and TOK, the response language must be English, French or Spanish, with some subjects offering additional languages. A student may not write in their strongest language and translate before submission, whether by a person or by software. The same response language must be used across all components of a subject. (Source: General regulations, article 9.)', 'structure groups six subjects higher standard level HL SL core hours', false, 9);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '2.2', 'Scoring', '2. THE PROGRAMME AT A GLANCE', '[OFFICIAL] Each of the six subjects is graded 1 to 7. HL and SL are worth the same maximum: 7 points each. Six subjects give a maximum of 42. TOK and the extended essay are each graded A to E and combine through a published matrix to contribute 0 to 3 further points. Maximum total: **45**. CAS is not graded and contributes no points, but must be completed. (Sources: ibo.org "Diploma programme assessment"; General regulations, article 11.)

**The TOK/EE core points matrix** [OFFICIAL]:

| | **EE: A** | **EE: B** | **EE: C** | **EE: D** | **EE: E** |
| --- | --- | --- | --- | --- | --- |
| **TOK: A** | 3 | 3 | 2 | 2 | Failing condition |
| **TOK: B** | 3 | 2 | 2 | 1 | Failing condition |
| **TOK: C** | 2 | 2 | 1 | 0 | Failing condition |
| **TOK: D** | 2 | 1 | 0 | 0 | Failing condition |
| **TOK: E** | Failing condition | Failing condition | Failing condition | Failing condition | Failing condition |

The matrix is symmetric. An A in one and a D in the other gives 2 points regardless of which is which.

[DERIVED] Three consequences students consistently miss:

1. **An E in either component is fatal regardless of total points.** A student on 43 points with an E in TOK does not receive the diploma. This is the single highest-leverage fact in the whole core.
2. **A C in either component caps the pair at 2 points and often at 1.** The jump from C to B in TOK is worth up to a full point of the total 45 if the EE is already strong.
3. **The cheapest core point in the system is usually the second-best of the two grades.** If a student is heading for an A in the EE and a C in TOK, moving TOK from C to B moves the pair from 2 to 3. Moving the EE from A to A does nothing. Improve the weaker of the two.', 'points score 45 total bonus matrix how many points', false, 10);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '2.3', 'The diploma award conditions in full', '2. THE PROGRAMME AT A GLANCE', '[OFFICIAL] The diploma is awarded only if **all** of the following hold. Missing any one withholds the diploma no matter how high the total. (Source: IB published passing criteria, reproduced consistently across IB coordinator materials and the *Diploma Programme Assessment procedures*.)

1. CAS requirements have been met.
2. Total points are 24 or more.
3. There is no grade **N** (no grade awarded) for TOK, the EE, or any contributing subject.
4. There is no grade **E** in TOK and/or the EE.
5. There is no grade **1** in any subject at any level.
6. There are no more than **two grade 2s** across HL and SL combined.
7. There are no more than **three grades of 3 or below** across HL and SL combined.
8. The candidate has **12 points or more** across HL subjects. If four HL subjects are registered, the three highest HL grades count towards this total.
9. The candidate has **9 points or more** across SL subjects. A candidate registered for only two SL subjects must reach at least 5 SL points.
10. The candidate has not received a penalty for academic misconduct from the Final Award Committee.

[DERIVED] Worked examples the system should be able to reproduce:

- **27 points, HL grades 4/4/3 = 11.** Diploma withheld. Fails condition 8 despite being three points clear of 24.
- **30 points, TOK D and EE D = 0 core points, subjects total 30.** Diploma awarded, provided all other conditions hold. Zero core points is survivable; an E is not.
- **24 points with grades 2, 2, 3, 5, 6, 6 and 0 core points.** Two grade 2s is allowed (condition 6 is a cap of two). Three grades of 3 or below (the two 2s and the 3) is allowed (condition 7 caps at three). Then check conditions 8 and 9 by level.
- **A student who does not submit one IA.** [OFFICIAL] If coursework is not submitted, no grade is awarded in that subject. That produces an N, which triggers condition 3, which withholds the diploma. A missing IA is therefore not a partial loss. It is a diploma failure. This is worth stating bluntly to any student who is considering skipping a coursework submission.', 'pass fail diploma awarded conditions requirements failing conditions', false, 11);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '2.4', 'Course results (formerly "certificates")', '2. THE PROGRAMME AT A GLANCE', '[OFFICIAL] A student who does not satisfy the diploma requirements receives **DP Course Results**, listing individual subject grades, TOK and EE results, and confirmation of CAS completion. Students may also register as course candidates from the outset, taking individual subjects without attempting the full diploma. (Source: General regulations, article 11.)', '', false, 12);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '2.5', 'Bilingual diploma', '2. THE PROGRAMME AT A GLANCE', '[OFFICIAL] A bilingual diploma is awarded where either:

- the student completes two studies-in-language-and-literature (group 1) subjects in different languages, with grade 3 or higher in each; or
- the student completes a group 3 or group 4 subject in a language different from their group 1 language, with grade 3 or higher in both.

(Sources: ibo.org "Diploma programme assessment"; General regulations, article 11.)

[DERIVED] Levels do not matter for eligibility. Both can be SL. The threshold is a grade 3, not a high grade.

[STRATEGY] The second route is often the cheaper one at schools that already teach a group 3 or 4 subject in the local language. The double group 1 route removes the group 2 slot and doubles the literary essay load, which is a real workload cost in year one.', '', false, 13);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '2.6', 'Scale of the programme (context for realistic advice)', '2. THE PROGRAMME AT A GLANCE', '[OFFICIAL, May 2026 session] 209,607 students in 3,442 schools across 159 countries received DP and CP results. Global average diploma score: **30.88**. Mean subject grade: 4.93. Diploma pass rate: **82.61%**. Students scoring above 40 points: 10,526. (Sources: ibo.org news release, 6 July 2026; *Tes*, 6 July 2026.)

[OFFICIAL, May 2025 final statistical bulletin] Pass rate 81.9%, mean total 30.6, mean subject grade 4.9, 102,233 second-year diploma candidates.

[STRATEGY] Useful calibration for students. A 40+ score is achieved by roughly one in ten full diploma candidates and about 5% of all students receiving results. Pandemic-era averages of 33.0 (2021) and 32.0 (2022) are not the baseline and will not return. Advice that treats 38 as a normal outcome is miscalibrated.

[OFFICIAL] Note on the May 2026 session specifically: students at schools in parts of the Middle East where examinations could not be held safely were graded through the IB''s Non-Exam Contingency Measure, using externally assessed coursework, teacher predicted grades, and additional evidence. Those results are included in the global figures.

---', '', false, 14);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3', 'HOW IB ASSESSMENT ACTUALLY WORKS', null, 'This section is the engine room. Most high-value student strategy is downstream of understanding it. Primary source throughout: *IB assessment principles and practices: A guide to assessment for teachers and coordinators* (ibo.org), plus *Diploma Programme Assessment procedures 2026*.', '', false, 15);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.1', 'Marks versus grades', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] Marking and grading are different operations. A mark records how much of the task the candidate completed correctly against a markscheme. It has no meaning beyond that. A grade is a judgment about the quality of the work against a defined standard, taking into account how difficult the task turned out to be.

The IB''s own analogy: marks measure how far a candidate walked; grades take into account how steep the path was.

[DERIVED] This is why "what percentage do I need for a 7" has no fixed answer, and why students who chase a percentage target rather than a standard are optimising the wrong variable.', 'raw mark grade boundary scaled percentage', false, 16);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.2', 'Scaling: how components combine', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] Components have different raw mark totals and different weightings. Raw marks are scaled so that the weighted total comes to 100.

Worked example, current Biology (first assessment 2025):

| Component | Raw max | Weighting | Scaling factor |
| --- | --- | --- | --- |
| Paper 1 | 75 (HL) | 36% | 36/75 |
| Paper 2 | 80 (HL) | 44% | 44/80 |
| Internal assessment | 24 | 20% | 20/24 |

Total raw available 179, scaled to a maximum of 100. The scaled total is then read against the subject grade boundaries.

[DERIVED] Three practical consequences:

1. **A mark on a low-raw-total, high-weight component is worth more than a mark elsewhere.** In the Biology example above, one IA mark is worth 20/24 = 0.833 scaled points. One Paper 1 mark is worth 36/75 = 0.48 scaled points. **One IA mark is worth roughly 1.7 Paper 1 marks.** This is the arithmetic behind most IA-first advice and it is worth computing per subject rather than assuming.
2. **Grade boundaries published as percentages refer to the scaled total, not to any single paper.** A student who scores 68% on Paper 2 has not scored 68% overall.
3. **Component boundaries published in subject reports are diagnostic, not targets.** The IB has explicitly advised schools not to treat component boundaries from unusual sessions as indicators of standards for future preparation.', 'scaling weighting components combine paper weight', false, 17);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.3', 'How grade boundaries are set', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] Grade awarding happens shortly before results are issued. Senior examiners, including the principal examiner, and IB staff set the boundaries using a combination of:

- examiner judgment about the quality of work at each boundary,
- statistical evidence,
- the published grade descriptors,
- **G2 forms** submitted by teachers, which record teachers'' perceptions of how difficult each paper was.

[DERIVED] Boundaries move to correct for paper difficulty. A lower boundary in a given session usually means the paper was harder than intended, not that standards were relaxed. A student cannot know the boundary during the exam and should not plan around a predicted boundary.

[STRATEGY] The correct use of historical boundaries is calibration of effort across subjects, not target setting. If a subject has historically required a high raw percentage for a 7 and another has not, that tells a student where the marginal hour is best spent. It does not tell them what they will need this session.

[STRATEGY] Cross-subject boundary patterns that experienced teachers rely on, offered as observations rather than rules: language acquisition subjects taken by near-native speakers (English B HL is the classic case) tend to carry unusually high grade 7 boundaries because the descriptors assume high fluency. Mathematics: applications and interpretation tends to require a lower raw percentage for a 7 than Analysis and approaches, which surprises students who assume AI is simply "the easier course". Mathematics carries the lowest subject mean of any group. [UNCERTAIN] These are patterns across recent sessions, not published rules, and can shift.', 'grade boundaries set awarding how many marks for a 7', false, 18);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.4', 'Quality control on external marking', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] Before marking starts, a standardisation meeting sets the marking standard. The markscheme is finalised there. Examiners then pass through three stages:

1. **Practice.** They mark responses already definitively marked by the principal examiner and receive automatic feedback.
2. **Qualification.** They must demonstrate they can apply the markscheme. An examiner who cannot qualify is not permitted to mark.
3. **Live marking with seeds.** Pre-marked responses ("seeds") are injected randomly into an examiner''s allocation without their knowledge. Each subject has a **tolerance**, an allowed deviation reflecting legitimate differences of judgment between competent markers.

[OFFICIAL] Responses are anonymised and randomly allocated to prevent bias. Many papers are marked by item: split into question item groups so that examiners mark one question at a time across many scripts, with separate monitoring and tolerance per group.

[DERIVED] Two things follow. First, "my examiner had a bad day" is a weaker hypothesis than students assume, because of seeding. Second, because papers are often marked question by question by different examiners, a script has no narrative continuity to an examiner. Every answer must stand on its own. Referring back to "as I argued in question 3" is a real risk.', '', false, 19);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.5', '"At risk" re-marking', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] Before results are issued, the IB identifies candidates whose final grades are at risk of being too low relative to their predicted grades, and re-marks them. This happens automatically and is intended to catch borderline candidates and detect undetected marking problems.

[DERIVED] This is one of the few places where a predicted grade has direct mechanical consequence for a student''s result, and it is a reason why deliberately depressed predicted grades are not costless.', '', false, 20);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.6', 'Internal assessment moderation', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] The teacher marks every student''s IA against the published criteria. The IB then requests a sample and moderates it. The purpose is to check whether the teacher applied the criteria at the global standard across the mark range.

Key mechanics [OFFICIAL]:

- The IB uses **dynamic sampling**.
- The sample is chosen to represent the school''s mark range.
- **The IB tends not to select candidates who received full marks, specifically so that candidates in the higher range retain the possibility of being moderated upwards.**
- Based on statistical comparison between the two sets of marks, an adjustment is applied to **all** the teacher''s marks for that component at that school, not only the sampled students.
- If the teacher is consistently harsh or lenient, the adjustment is uniform. If the teacher is harsh or lenient only at one end of the range, the adjustment varies across the range.
- Where the sample is insufficient to compute a fair adjustment, more work is requested. **All candidates'' work must remain available until the close of the session** (15 September for May; 15 March for November).
- Only schools whose marks are adjusted receive IA feedback, and the feedback must explain the adjustment.
- Examiners are instructed to accept the teacher''s assessment where it is reasonable to do so.

[DERIVED] Consequences students should understand:

1. **The teacher''s mark is provisional.** It is a well-informed estimate, not a result.
2. **Moderation moves in both directions.** A conservatively marking teacher can lift a whole cohort.
3. **A student cannot influence sample selection.** The teacher cannot protect a borderline student by excluding them, and a student cannot volunteer.
4. **The adjustment is cohort-wide.** A student''s moderated mark depends partly on how their classmates'' work was marked. This is uncomfortable but true.

[STRATEGY] The only real defence is to make the work *easy to award marks to*. Moderators work fast, against criteria, on screen. Explicit signposting of criterion evidence, clear structure, labelled figures, and explicit justification of choices are worth marks not because they are elegant but because they make the evidence unmissable. Work that requires the moderator to infer credit tends to lose it.', 'moderation teacher mark changed lowered sample', false, 21);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.7', 'Predicted grades', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL/UNCERTAIN] Predicted grades are the subject teacher''s judgment of the grade the student is expected to achieve in the final examinations, informed by internal assessments, mock examinations, coursework and classroom evidence, interpreted against the IB grade descriptors. They are submitted to the IB by the school and used for university applications. There is no formula and no algorithm.

[OFFICIAL] Predicted grades feed the "at risk" re-marking process (3.5).

[DERIVED] The IB does not set predicted grades and has no mechanism to alter them. There is no IB appeals route for a predicted grade. Any change happens inside the school, under the school''s own policy, before submission.

[STRATEGY] What actually moves a prediction, in rough order of leverage: mock examination performance under proper conditions; a strong IA submitted on time; a demonstrable upward trajectory across timed assessments rather than a single good result. What does not move it: appealing on the basis of ambition. A student contesting a prediction should bring specific evidence (IA mark, mock script, assessment history) rather than a target.

[STRATEGY] Timing matters more than students realise. Predictions are typically finalised in the first term of year two, aligned to application deadlines. That means the evidence base is largely built in year one and the first term of year two. A student who plans to "turn it around in the spring" will do so after the prediction has already been submitted.', 'predicted grades university offer', false, 22);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.8', 'Enquiry upon results (remarks)', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] After results are issued, the coordinator may request:

| Category | What it is |
| --- | --- |
| **Category 1** | Re-mark of all of a candidate''s externally assessed components for a subject, by a senior examiner. |
| **Category 1 report** | A report on the marking of a category 1 enquiry. |
| **Category 2** | Copies of externally assessed component material returned to the school. (Sub-categories exist for material with and without examiner comments.) |
| **Category 3** | Re-moderation of a school''s sample of an internally assessed component. |

[OFFICIAL] Key rules:

- All enquiries must be submitted by the school on behalf of the student. Students cannot request them.
- A re-mark can raise **or lower** the grade. Written consent from the student or legal guardian is required before submission, confirming they understand this.
- A fee is payable for each category, **refunded when a grade changes as a result of a category 1 re-mark**.
- Beyond the enquiry service, the coordinator cannot request further re-marking or re-moderation. The remaining route is a formal appeal (3.10).

[UNCERTAIN] The request window in recent sessions has run from results day (early July for May sessions) to roughly mid-September, with category 1 outcomes typically returned within two to three weeks. Fees have been reported in the region of 89 euros to 120 US dollars per subject. **Exact dates and fees are set per session in the Assessment procedures and must be confirmed with the coordinator.** Schools routinely set internal cut-offs earlier than the IB deadline.

[STRATEGY] A decision framework the system can offer:

- **Strongest case:** the grade sits just below a boundary, and that one grade determines something real (diploma award, a university offer, a scholarship, a subject prerequisite). The coordinator can see how close each grade was to the next boundary and is the single best source of information before paying.
- **Weak case:** the grade is a full band away, or the student is simply disappointed. A retake plan is usually the better instrument.
- **Category 2 first, then decide** is a legitimate sequence when a result looks anomalous and the family wants to understand why before risking a downward move.
- Reported success rates for category 1 grade increases circulate in the region of 10 to 15 percent. [UNCERTAIN] The IB does not publish this figure. Treat it as folklore with a plausible order of magnitude, not data.', 'remark enquiry upon results EUR recheck challenge grade', false, 23);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.9', 'Adverse circumstances', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] Adverse circumstances are situations arising during the examinations or up to three months before them, beyond the control of the student and the school, which affect performance in IB assessments. They may affect an individual, a group, or an entire cohort. The IB''s approach, what counts and what does not, and the available actions are set out in the *Diploma Programme Assessment procedures*. (Source: General regulations, article 15.)

[OFFICIAL] Where an entire cohort cannot sit examinations, the IB has used a **Non-Exam Contingency Measure (NECM)**, awarding grades from externally assessed coursework, teacher predicted grades and additional supporting evidence reviewed by the IB. This was applied in the May 2026 session for schools affected by regional conflict in parts of the Middle East.

[DERIVED] The three-month window matters. A bereavement or serious illness in February for a May candidate is inside the window. One in the previous September is not, and would be handled differently by the school. Students should report circumstances to the coordinator immediately rather than after results.', '', false, 24);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.10', 'Appeals', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] An assessment appeal asks the IB to review **how a decision was made**, either the processing of a grade or the handling of an academic misconduct case. Rules (General regulations, article 17):

- An appeal cannot request an exception to an IB process, but it can challenge whether the interpretation of IB rules was reasonable.
- An appeal cannot change published IB policy. Where an appeal clarifies a rule, that clarification must be applied to all students in the session.
- An appeal is the final step. Its outcome cannot be escalated further inside the IB. This does not remove the legal right to complain to a national regulator or seek arbitration.
- Only the Head of School or the DP coordinator may raise an appeal. **The school must submit an appeal on a student''s behalf if asked, even if the school does not support it.** Whether the school charges the family is a school decision.
- The process has two stages, each normally carrying a fee, refunded if the decision changes.

[OFFICIAL] For misconduct decisions specifically, an appeal will only be considered where there is evidence the IB failed to follow its own process, or new evidence exists that was unknown at the time.', '', false, 25);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.11', 'Access arrangements (inclusive assessment)', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] The IB''s position is that access arrangements do not change what a student is expected to learn and do not lower expectations. They remove barriers so the student can demonstrate what they know. The framework is set out in the *Access and inclusion policy*, with the request procedure in the Assessment procedures. (Source: General regulations, article 14.)

[OFFICIAL] Requests must be made by the coordinator through IBIS with supporting evidence, and require IB authorisation before they can be used in examinations. Arrangements used only in the examination and not in teaching and learning are not the model the IB intends; arrangements should reflect the student''s normal way of working.

[OFFICIAL] Results of students with authorised inclusive assessment arrangements are not flagged or annotated in any way.

[UNCERTAIN] Commonly authorised arrangements reported by schools include additional time (frequently 25 percent, with larger allocations possible where evidence supports it), use of a word processor, a reader and/or scribe, supervised rest breaks that pause the clock, a separate room, and permission to move. Deadlines for requests are session-specific; schools commonly work to a mid-November deadline for the following May session. **Confirm the current deadline and the current list with the coordinator; do not state these as fixed.**

[OFFICIAL] Giving a student additional time without IB authorisation is school maladministration and carries sanctions against the school (see 5.7).', 'extra time access arrangements inclusive dyslexia ADHD support', false, 26);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.12', 'Retakes', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] Candidates may retake a subject in any future examination session, at any IB World School offering the programme. Restrictions apply and must be checked with the coordinator at the receiving school. **A school is under no obligation to accept a retake candidate.** (Source: ibo.org "Retaking examinations".)

[OFFICIAL] **The former limit of three examination sessions has been removed.** The IB states that students are no longer restricted to a maximum of three sessions, and that this applies to previous, current and future students. Any source stating a three-session cap is out of date.

[OFFICIAL] If a subject is retaken to improve a result, **the highest grade contributes to the award of the diploma**. The same normally applies where an anticipated subject is retaken in the diploma session.

[OFFICIAL] If a subject has changed curriculum since the original sitting, the retake follows the new curriculum.

[OFFICIAL] Where a response language is unavailable in the target session, internal assessment can be carried over from a previous session, which can result in more than one response language across a single subject.

[UNCERTAIN] Whether internal assessment carries forward, and whether coursework may be resubmitted or must be newly produced, depends on the component, the candidate''s history and current regulations. Widely reported that IA marks commonly carry forward, and that TOK and EE work can be resubmitted. **This must be confirmed with the coordinator before registration; it is one of the highest-consequence uncertainties in the retake process.**

[OFFICIAL] Where academic misconduct has been established, the student cannot reuse the work under investigation. A retake in that subject requires an entirely new piece of coursework.

[DERIVED] A subject retake cannot repair a core failure. If the diploma was withheld because of an E in TOK or an unmet CAS requirement, retaking Chemistry does not help. Diagnose which condition failed first (see Section 2.3), then choose the instrument.', 'retake resit again november may repeat', false, 27);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.13', 'Grade N and mark F', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] **N** means no grade awarded. It is triggered by non-submission of a required component, or by a level 3a academic misconduct penalty. An N in TOK, the EE, or any contributing subject withholds the diploma.

[OFFICIAL] Where a school identifies before submission that a final piece of work is plagiarised or does not meet subject guide requirements, the component should be recorded as **F** on the IA mark entry system, or as non-submission for externally assessed components such as the EE or TOK essay, and the student is not eligible for a final grade in that subject. **A school should not submit work with a mark of zero as a workaround, and should not submit work it believes is not the student''s own.**', '', false, 28);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.14', 'Copyright and return of work', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] Students retain copyright in submitted materials, but by submitting they grant the IB a broad non-exclusive licence to reproduce the work for assessment, educational, training, commercial and promotional purposes. The IB may anonymise work; where it is publishing work of a particularly high standard, the student and school may be identified, with prior notice to the school. Students may withdraw the non-assessment aspects of the licence for a specific piece of work by written notification through the coordinator by the published deadline. All submitted materials become the property of the IB. (General regulations, article 6.)

[OFFICIAL] A student may request a copy of their externally assessed work, applied for by 15 September for a May session or 15 March of the following year for a November session, submitted through the coordinator.', '', false, 29);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.15', 'Examination conduct rules students actually need', '3. HOW IB ASSESSMENT ACTUALLY WORKS', 'Source: *Conduct of examinations booklet 2026*.

- [OFFICIAL] **Five minutes of reading time** precedes papers where it applies. During reading time students may not write, use a dictionary, **highlight questions**, or use a calculator.
- [OFFICIAL] Announcements are made at 30 minutes and 5 minutes remaining.
- [OFFICIAL] **Late arrival:** a student arriving late should be allowed to sit the paper with the **full time** applied, as soon as they arrive at school. Arrival within one hour of the start is reported by the school through a survey; arrival more than one hour after the start requires the school to contact the IB via the adverse circumstances route.
- [OFFICIAL] Students must not remove examination papers, data booklets, answer booklets or graph paper from the room.
- [OFFICIAL] Students must never be left unsupervised, including during bathroom breaks.
- [OFFICIAL] Only the student cohort, the Head of School, the coordinator, invigilators and authorised IB inspectors may enter the examination room.
- [OFFICIAL] Calculators must comply with the current *Use of calculators in IB DP examinations* document. A calculator is not permitted if it has functionality unique to prohibited models, or if it retains third-party applications or student-generated notes that have not been removed by reset or blocked by examination mode. Checking calculators is the school''s responsibility; failure to check is maladministration.
- [OFFICIAL] Possession of unauthorised material in the examination room is a breach **regardless of intent and regardless of whether it was used**. See the penalty structure in 5.4.', '', false, 30);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '3.16', 'The 24-hour rule', '3. HOW IB ASSESSMENT ACTUALLY WORKS', '[OFFICIAL] Students must not discuss or share examination content for a **24-hour period after the examination ends**, out of fairness to students in other time zones who have not yet sat it. This applies to social media, private group chats, and conversations. Sharing live content within that window is treated as conduct threatening the integrity of the examination and attracts a level 3a penalty: no grade for the subject concerned.

[DERIVED] Documented precedent: a student posted on social media within the window expressing pleasure that a question matched their EE topic, including details of the question. Level 3a penalty applied. A student posted a photograph of a paper stimulus. Level 3a. A student shared paper content in a group chat spanning time zones. Level 3a. In one case a student offering fragmentary content after their papers received a level 3a **across all subjects with permanent disqualification**, and other students in the group were also penalised.

[STRATEGY] The practical rule to give students: after any paper, say nothing about its content anywhere, to anyone, for a full day. Including to classmates. Including in a closed group. Including "that was so easy" attached to a topic name.

---', '', false, 31);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '4.1', 'Why they matter mechanically', '4. COMMAND TERMS', '[OFFICIAL] Command terms indicate what a question requires and signal the expected depth of response. They are tied to assessment objectives, though the exact classification and mark tariffs differ between subjects. **The subject guide''s own definitions are authoritative where they differ from any general list.**

[DERIVED] The commonest single cause of avoidable mark loss in IB written papers is performing the wrong cognitive task: describing when asked to analyse, explaining when asked to evaluate, listing when asked to compare. The content can be correct and the marks still unavailable, because the markscheme rewards the operation, not the recall.', '', false, 32);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '4.2', 'The glossary', '4. COMMAND TERMS', 'Definitions below are the IB''s standard formulations, paraphrased. The "what this actually requires" and "failure mode" columns are [STRATEGY].

**Assessment objective 1: knowledge and understanding**

| Term | IB sense | What it actually requires | Failure mode |
| --- | --- | --- | --- |
| **Define** | Give the precise meaning of a word, phrase, concept or quantity. | The technical definition, not an example. | Substituting an example for a definition. |
| **State** | Give a specific name, value or other brief answer without explanation or working. | One line. Stop. | Writing a paragraph and losing time. |
| **List** | Give a sequence of brief answers with no explanation. | Bullet-level answers. | Explaining each item. |
| **Identify** | Provide an answer from a number of possibilities. | Selection, not justification. | Justifying at length. |
| **Outline** | Give a brief account or summary. | The shape of the thing, not the detail. | Full explanation, over-length. |
| **Label / Draw** | Add labels; represent by means of a diagram or graph. | Precision, labelling, and where required a ruler and scale. | Unlabelled axes, no units. |

**Assessment objective 2: application and analysis**

| Term | IB sense | What it actually requires | Failure mode |
| --- | --- | --- | --- |
| **Describe** | Give a detailed account. | What happens, in detail, without causes. | Drifting into "why" and running out of time. |
| **Explain** | Give a detailed account including reasons or causes. | Explicit causal chains. The word "because" should appear. | Describing rather than causing. |
| **Distinguish** | Make clear the differences between two or more items. | Paired differences, both items in each point. | Two separate descriptions. |
| **Apply** | Use an idea, equation, principle, theory or law in a new situation. | Transfer, not recall. | Reciting the theory without touching the stimulus. |
| **Calculate** | Obtain a numerical answer, showing the relevant stages of working. | Visible working, correct units, appropriate significant figures. | Answer only; working absent, so method marks are lost. |
| **Estimate** | Obtain an approximate value. | A justified approximation, not a guess. | No reasoning shown. |
| **Annotate** | Add brief notes to a diagram or graph. | Notes that add information, not restated labels. | Labelling instead of annotating. |
| **Analyse** | Break down in order to bring out the essential elements or structure. | Relationships, mechanisms, patterns, implications. | Description with the word "analyse" attached to it. |
| **Suggest** | Propose a solution, hypothesis or other possible answer. | A plausible, reasoned proposal. Uncertainty is permitted. | Refusing to commit. |
| **Interpret** | Use knowledge and understanding to recognise trends and draw conclusions from given information. | Trend plus meaning. | Reading numbers aloud. |

**Assessment objective 3: synthesis and evaluation**', 'command term evaluate discuss analyse compare contrast explain justify outline describe state suggest examine to what extent verb', false, 33);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '4.2p2', 'The glossary (continued)', '4. COMMAND TERMS', '| Term | IB sense | What it actually requires | Failure mode |
| --- | --- | --- | --- |
| **Compare** | Give an account of the similarities between two or more items, referring to all of them throughout. | Integrated similarities. The word "throughout" is doing real work: both items in each paragraph. | Two sequential mini-essays. |
| **Contrast** | Give an account of the differences, referring to all of them throughout. | As above, differences. | As above. |
| **Compare and contrast** | Both, referring to all items throughout. | Both operations, integrated. | Doing only one of the two. |
| **Discuss** | Offer a considered and balanced review including a range of arguments, factors or hypotheses, with opinions or conclusions presented clearly and supported by evidence. | A credible range of positions, then a supported position. Balance does not mean equal space for every view. | Listing views with no synthesis and no landing point. |
| **Evaluate** | Make an appraisal by weighing up strengths and limitations. | Explicit criteria, weighing, and a judgment that follows from the weighing. | Strengths and limitations listed, no judgment. This is the single commonest capped answer in the IB. |
| **To what extent** | Consider the merits or otherwise of an argument or concept, with evidence and reasoned argument. | A degree, defended. "To a significant extent, because..." | Answering the topic and never stating an extent. |
| **Examine** | Consider an argument or concept in a way that uncovers the assumptions and interrelationships of the issue. | Surfacing what is being taken for granted. | Treating it as a synonym for "describe". |
| **Justify** | Give valid reasons or evidence to support an answer or conclusion. | Reasons that could persuade a sceptic. | Assertion. |
| **Comment** | Give a judgment based on a given statement or result of a calculation. | A short evaluative statement, anchored to the given thing. | Ignoring the anchor. |
| **Deduce** | Reach a conclusion from the information given. | Logical necessity from the stimulus. | Importing outside information. |
| **Demonstrate** | Make clear by reasoning or evidence, illustrating with examples or practical application. | Show, do not assert. | Assertion. |
| **Recommend** | Present an advisable course of action with supporting evidence in relation to a situation, problem or issue. | A decision plus its justification plus its trade-offs. | A wish list. |
| **Predict** | Give an expected result. | An outcome, ideally with the reasoning behind it. | Hedging. |
| **Formulate** | Express precisely and systematically the relevant concept or argument. | Precision of statement. | Vagueness. |
| **Investigate** | Observe, study, or make a detailed and systematic examination in order to establish facts and reach new conclusions. | A method plus findings. | Opinion. |
| **Prove / Show that / Derive** | Use a sequence of logical steps to obtain the required result in a formal way. | Every step visible; the target result must appear at the end. | Working backwards from the answer, or skipping algebra. |', '', false, 33);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '4.3', 'Command term strategy', '4. COMMAND TERMS', '[STRATEGY] Rules that reliably convert to marks:

1. **Write the operation, not just the topic.** Before answering an extended response, name the verb to yourself. "Evaluate = criteria, weighing, judgment." Structure the answer to perform that.
2. **Match effort to tariff, not to interest.** A two-mark "explain" needs two creditable points. A nine-mark "discuss" needs range and a conclusion. Students routinely overspend on low-tariff questions and then arrive under-timed at the high-tariff ones, where the marks actually are.
3. **Every evaluation must land.** If the final sentence does not make a choice, the answer is usually capped below the top band regardless of quality above it. Force a closing sentence of the form "Overall, X is more convincing because..." or "To a limited extent, because...".
4. **Compare means interleave.** Structure comparison paragraphs by point of comparison, not by item. Two separate item descriptions almost never reach the top band, no matter how good each one is.
5. **In quantitative subjects, working is mark-bearing.** Answers alone forfeit method marks. Where a calculator is permitted, still show the stages.
6. **Do not import a second command term.** A "discuss" question answered as an "evaluate" (or vice versa) drifts off the markscheme. In essay subjects, keep the question''s own verb in the thesis statement.

---', 'answer the question marks lost misread verb', false, 34);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5', 'ACADEMIC INTEGRITY', null, 'Primary source throughout: *Academic integrity policy*, International Baccalaureate, published October 2019, updated March 2023, with Appendix 6 (artificial intelligence) added in that update. Schools commonly cite a March 2025 refresh; the substantive rules below are stable across those versions. Supplementary: General regulations articles 3.3, 3.4, 16; *Effective citing and referencing*.

This is the section with the highest consequence per word. A student who misunderstands it can lose a subject grade and therefore the diploma.', '', false, 35);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5.1', 'The two definitions', '5. ACADEMIC INTEGRITY', '[OFFICIAL] **Student academic misconduct** is deliberate **or inadvertent** behaviour that has the potential to result in the student, or anyone else, gaining an unfair advantage in one or more assessment components. Behaviour that may disadvantage another student also counts. So does any act that threatens the integrity of IB examinations and assessments, before, during or after completion, paper-based or on-screen, in school, out of school, or online.

[OFFICIAL] **School maladministration** is an action by a school or an individual associated with it that infringes IB rules and potentially threatens the integrity of examinations and assessments.

[DERIVED] Three features of the student definition that students consistently misread:

1. **Intent is not required.** "I forgot the bibliography" is not a defence. It is documented as a real case that produced a level 3a penalty.
2. **Failing to report observed misconduct is itself misconduct** and carries a level 3a penalty. A student who knows a classmate is cheating and says nothing is exposed.
3. **The scope includes conduct outside school and online.**

[OFFICIAL] Where evidence is not conclusive, decisions are made on the **balance of probabilities**: the decision-maker is satisfied the event more likely than not occurred. Intent is not weighed in the deliberation.', '', false, 36);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5.2', 'The penalty levels', '5. ACADEMIC INTEGRITY', '[OFFICIAL] Four levels:

| Level | Consequence |
| --- | --- |
| **Level 1** | Warning letter to the student. |
| **Level 2** | Zero marks for the component. |
| **Level 3a** | **No grade for the subject concerned.** Depending on seriousness, this can be extended to several or all subjects in the session. |
| **Level 3b** | No grade for "parallel" subjects. Applied to a student whose misconduct benefits another student rather than themselves. |

[DERIVED] A level 3a produces a grade **N**, which triggers diploma failing condition 3. **Any level 3a penalty in a contributing subject withholds the diploma**, regardless of points.

[OFFICIAL] Additional sanctions exist for repeated, multiple or very serious offences: a change of registration category to "course" (the student may retake but is no longer eligible for the full diploma), or permanent disqualification with no grade in any subject and no retake permitted.

[OFFICIAL] Retake options after a penalty are decided by the IB. Typical outcomes are: retake in six months subject to availability, retake in twelve months, or no retake with grades awarded in unaffected subjects.', 'penalty consequence caught punishment no grade awarded', false, 37);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5.3', 'The word-count thresholds (memorise these)', '5. ACADEMIC INTEGRITY', '[OFFICIAL] **Plagiarism, copying from external sources or peers:**

- **40 to 50 consecutive words** copied verbatim, paraphrased, or with words added or substituted, without full in-text citation: **level 2** (zero for component).
- **51 or more consecutive words** on the same basis: **level 3a** (no grade for the subject).

[OFFICIAL] **Collusion** (students submitting a common write-up rather than individual work) uses the same thresholds: close similarity is level 1; 40 to 50 copied words is level 2; 51 or more is level 3a.

[OFFICIAL] **The Extended Essay exception.** Because the EE is a single-component subject, level 2 and level 3a would produce the same outcome (non-award of the diploma). The Final Award Committee therefore ruled in November 2013 that **plagiarism in an EE is only considered where more than 100 consecutive words lack proper reference.**

[DERIVED] Two things follow that students find counter-intuitive:

1. **Paraphrasing without citation is plagiarised.** The thresholds explicitly cover paraphrase and word-substitution. Changing every third word does not make it yours.
2. **A correct bibliography does not save an uncited body.** Documented precedent: a candidate''s EE contained over 100 words of verbatim text from two internet sources, and the correct links were in the bibliography. Because there was no reference at the point of use, level 3a was applied and an N was awarded for the EE.', 'word count word limit too long over the limit maximum length how many words', false, 38);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5.4', 'The full infringement map', '5. ACADEMIC INTEGRITY', '[OFFICIAL] Beyond plagiarism and collusion:

| Infringement | Level 1 | Level 2 | Level 3a | Level 3b |
| --- | --- | --- | --- | --- |
| **Facilitating plagiarism** (sharing your work so it can be copied) | Minimal steps taken to prevent copying | No steps taken; shared to a forum where copying was likely | Permitted copying, or tried to sell or exchange own work where it was likely to be submitted by others ("selling" needs no money) | Actively tried to sell or exchange third-party work for others to submit |
| **Third-party work** (commissioned, edited by, or obtained from another) | | Heavily edited by a third party to circumvent teacher-support rules | Entirely produced or edited by a third party | Applies to a student providing the service |
| **Duplication of work** (same work for two components or subjects) | | Partial reuse; penalties applied to **both** subjects | Complete reuse; penalties applied to **both** subjects | |
| **Falsification of data** | Methodology overstates the rigour of data gathering | Data selected or discarded to improve conclusions, creating deliberate bias | Data fabricated, or data gathered by others presented as the student''s own | |
| **Inappropriate, offensive or obscene material** | Minor | Moderate | Major | Major |
| **Unauthorised material in the exam room** | Surrendered or removed within the first 10 minutes | In possession, no evidence of use | In possession **and** evidence of use | |
| **Misconduct or disruptive behaviour in an exam** | | Non-compliance with invigilator instructions in one component | Repeated non-compliance in one exam, or non-compliance across two or more exams | |
| **Exchanging information during an exam** | | | Any attempt, successful or not, to share answers or content. Applies to all participants | For a student aiding others in a subject they are not registered for |
| **Removing secure materials from the exam room** | | Attempted, caught before leaving | Successfully removed | |
| **Impersonation** | | | Both the impersonator and the person allowing it | For the impersonator |
| **Failing to report known misconduct** | | | Applies | Applies |
| **Accessing live exam content before the scheduled time** | Immediate self-report is treated as mitigating and may avoid a penalty entirely | In possession of partial or complete live content | | |
| **Sharing exam content before, during, or within 24 hours after** | | | Any sharing by any means, **even if the shared information is general** | Assisting the sharing |
| **Interfering with an investigation** (non-cooperation, false information, influencing witnesses, threatening behaviour, refusing to submit a statement) | | | Applies | Applies |
| **Forging or falsifying IB grades or certificates** | Attempted amendment of a result | | | Applies, with additional sanctions by number of subjects affected |

[OFFICIAL] Categories of "inappropriate, offensive or obscene material" include, at moderate level, field experiments or investigations that inflict pain or risk the wellbeing or survival of live organisms, and research or fieldwork that damages the environment. At major level: work denigrating personal, political or spiritual values or containing offensive remarks about race, gender or religious belief; fabrication of data; and gratuitously violent or sexually explicit content.

[OFFICIAL] Unauthorised materials include but are not limited to mobile phones, notes, study guides, **the student''s own rough or scratch paper**, non-permitted dictionaries, and smart watches or smart glasses.', '', false, 39);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5.5', 'Documented precedent cases', '5. ACADEMIC INTEGRITY', '[OFFICIAL, from the published policy] These are real outcomes and are useful for making the rules concrete:

- **EE, over 100 verbatim words, correct bibliography, no in-text citation.** Level 3a, N for the EE, diploma not awarded.
- **English A literature oral delivered from memorised internet material, unreferenced.** The student said they did not know memorised material had to be referenced in an oral. Level 3a, N for the subject.
- **Four students in one school reproduced memorised internet material in History paper 3 responses.** All four received level 3a and N for History of the Americas HL.
- **TOK essay almost entirely plagiarised from an English source translated into Spanish.** The student said they did not know translated sources needed referencing. Level 3a.
- **Peer plagiarism, Economics IA.** Student A asked to see Student B''s draft "for structure". B shared it and explicitly asked A not to copy. A submitted it. **A received level 3a and an N. B received a level 1 warning.**
- **TOK essay shared between friends at different schools.** Student B rewrote part of A''s essay and left sections unchanged. **Both received level 3a.**
- **ESS IA, two students submitted identical work** despite instruction to collect and record their own data. Both level 3a.
- **ESS EE expanded from a Mathematics SL IA.** Extensive similarity. Level 3a and N **in both subjects**.
- **Biology SL paper 1, phone forgotten in pocket, surrendered voluntarily during reading time.** Level 1 warning.
- **Chemistry HL paper 1, phone alarm sounded mid-exam, no evidence of use.** Level 2, zero for the paper.
- **Business management paper 2, phone found, browser history showed searches for answers.** Level 3a, N for the subject.
- **Mathematics HL paper 1 (non-calculator), an examiner flagged an answer not achievable without a calculator.** School and student denied it. Subject experts consulted. On the balance of probabilities, level 3a and N.
- **Physics SL paper 1, student refused allocated seat, became aggressive, removed from the hall.** Level 2.
- **Psychology SL paper 2, student receiving answers through concealed wireless headphones via a cough code from a student in another room.** Both permanently disqualified.
- **Visual arts HL exhibition, work copied from a known painter''s technique without acknowledgement**, the student claiming inspiration after seeing an exhibition. Level 3a, N for the subject.

[STRATEGY] The pattern across every case: **the student''s explanation did not change the outcome.** "I did not know" is documented repeatedly and never mitigates. The one documented mitigating circumstance in the entire matrix is immediate self-reporting of possession of live examination content.', '', false, 40);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5.6', 'Artificial intelligence: the complete position', '5. ACADEMIC INTEGRITY', 'Source: *Academic integrity policy*, Appendix 6, "Guidance on the use of artificial intelligence tools", added March 2023; plus the IB''s public statement on ChatGPT and AI in assessment and education (first published March 2023, most recently updated March 2025), and the AI in learning, teaching and assessment page on ibo.org.

**The IB''s stated position** [OFFICIAL]:

- The IB **will not ban** AI tools. It regards the alternative as the wrong way to handle innovation and expects such tools to become as routine as calculators and translation software.
- AI tools do not threaten the underlying principles the IB values. Students are already expected to research, which today means starting with a search.
- The IB explicitly declines to join the "arms race" of AI detection. It considers it better to ensure students can **speak about their own work with their teachers** than to accuse them based on small differences in word-choice predictability.
- The IB notes that AI-generated text is often repetitive and formulaic, and most likely not good enough to score highly.

**The rules students must follow** [OFFICIAL]:

1. **The IB does not regard any work produced, even in part, by such tools as the student''s own.**
2. If a student uses text or any other product from an AI tool, **whether by copying, paraphrasing, or modifying an image**, they must clearly credit the tool in the body of the work and add it to the bibliography.
3. **The in-text citation must use quotation marks**, in the referencing style the school already uses, and must contain **the prompt given to the tool and the date the content was generated**.
4. The same applies to any other category of AI output, including images.
5. Failure to do this is misrepresenting content that the student did not write. That is academic misconduct.

**Language and translation software** [OFFICIAL]:

- IB assessments generally do not award marks for spelling, punctuation and grammar, so there is limited benefit in using rewriting tools.
- **The exception is language acquisition, where marks are awarded for sentence structure. In those subjects the use of such tools is not permitted.**
- Students are **not permitted to write in one language and translate for submission in another**. This protects the meaning of the bilingual diploma and of language subject grades.
- Outside language acquisition, spell checkers and bilingual dictionaries are acceptable, and basic spelling and grammar support is allowed where that is not what is being assessed.
- Software supporting access and inclusion requirements is always considered separately under the *Access and inclusion policy*.

**Practices the IB explicitly endorses** [OFFICIAL]:

- Using a search engine to find research material before writing.
- Looking at an example of a good essay to understand structure and coherent argument, provided the student is clear they are studying the form and not copying content.
- **Asking AI research questions rather than the essay title**, then exploring the sources it provides and examining their inherent bias.

[OFFICIAL, from the IB''s published scenario guidance] Using an AI tool to generate a structural template for an essay and then completing the content yourself is **not** misconduct, **provided the use is acknowledged on submission**. The failure in that scenario is non-disclosure, not the use itself. The guidance is explicit that non-disclosure is unacceptable **even where the underlying use would have been acceptable**, and that this includes telling the teacher who authenticates the work even where formal referencing is not required.

**What teachers are confirming when they authenticate** [OFFICIAL]. This is the practical enforcement mechanism and students should understand it:

1. The teacher has seen the work develop over time. **IB coursework is not designed to be completed in a single evening.**
2. The student can explain their work sufficiently to give confidence they created it.
3. The student is clear about when they are quoting others'' ideas and when they are claiming something as their own.
4. The final quality is in line with what the teacher would expect that student to produce.

[OFFICIAL] If the teacher is not convinced, **the work must not be submitted to the IB**. Where a teacher has doubts, the recommended approach is a viva or oral quiz on the arguments and content.

[OFFICIAL] Teachers are strongly recommended to instruct students to **retain their developmental work**.

[STRATEGY] The operational advice to give a student is therefore not "avoid AI". It is:

- **Keep the audit trail.** Drafts, notes, a source log, dated files. This is the single strongest defence against any authenticity challenge, and it costs nothing.
- **Be able to explain every paragraph.** If a student cannot defend a sentence in conversation, that sentence is a liability regardless of how it was produced.
- **Disclose to the teacher.** The rule is not only about formal referencing; it extends to telling the person authenticating the work.
- **Do not use AI for language acquisition writing.** This is a hard prohibition, not a grey area.
- **Never translate into the response language.**

[DERIVED] Where this leaves an AI study assistant such as Albus. Explaining a concept, drilling exam technique, clarifying why a markscheme rewards certain phrasing, planning time, and giving criterion-referenced feedback on the student''s own draft are all squarely within what the IB endorses. Generating assessed prose for the student is not. The system should hold that line explicitly and should tell students where the line is rather than silently declining.', 'AI ChatGPT artificial intelligence generative allowed cite acknowledge', false, 41);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5.7', 'Teacher support limits and school maladministration', '5. ACADEMIC INTEGRITY', '[OFFICIAL] Students are expected to produce work autonomously and should **not receive multiple rounds of editing**. Teachers are expected to provide comments in the margins, not to extend support into a full editing exercise.

[OFFICIAL] Two named forms of undue assistance constitute maladministration:

- **Templating**: preparing a template so all students follow a clear pattern or model. Even where well-intentioned as workload management, it restricts creativity and originality and negates the achievement expected of the student.
- **Over-editing**: multiple rounds of editing contrary to the subject guide''s instructions.

[OFFICIAL] Other maladministration includes allowing submission of third-party work, awarding zero for non-authentic work instead of withholding it, authenticating work where authenticity is doubted, having plagiarism cases in more than 20 percent of a cohort for a component, unauthorised additional time, insufficient or poorly trained invigilation, failing to check calculators and dictionaries, leaving students unsupervised, amending completed scripts before dispatch, and failing to report or support an investigation.

[OFFICIAL] Sanctions against schools range from recorded incidents and formal warning letters through mandated training, session monitoring for two to five consecutive sessions, immediate inspection visits, controlled dispatch of papers at the school''s expense, independent invigilators at the school''s expense, relocation of candidates, **annulment of grades for the candidates concerned or the entire cohort**, and withdrawal of authorisation.

[OFFICIAL] Where a school''s maladministration gave students an unfair advantage, **the IB requires the affected students to retake in a future session** in order to be eligible for a grade. The IB frames this not as a penalty on the student but as the consequence of the school''s failure.

[DERIVED] A student cannot control this, but should understand two things. First, accepting excessive help is not free: it exposes the whole cohort. Second, if a teacher offers to rewrite sections, the correct response is to ask for comments instead.', '', false, 42);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5.8', 'Referencing requirements', '5. ACADEMIC INTEGRITY', '[OFFICIAL] The IB does not mandate a particular citation system. It requires that students use a system appropriate to the subject discipline, apply it consistently, and acknowledge all ideas and work of other people **at the point of use**, not only in a bibliography. For longer work such as the historical investigation and the extended essay, footnotes are often appropriate. Oral components require citations to be made clear to the audience through verbal statement or visual cue.

[OFFICIAL] A student''s failure to acknowledge a source is likely to be investigated as a potential breach of regulations that may result in a penalty imposed by the Final Award Committee.

[STRATEGY] The minimum defensible standard, which costs a student almost nothing and removes almost all risk:

1. Cite at the point of use, every time, including for paraphrase.
2. Cite AI tools with the prompt and date.
3. Cite in orals, out loud.
4. Keep one consistent style throughout a single piece of work.
5. Never let a bibliography stand in for in-text citation.', 'citation referencing bibliography cite sources format', false, 43);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '5.9', 'Investigation process', '5. ACADEMIC INTEGRITY', '[OFFICIAL] Sequence, in outline:

1. Cases reach the IB from examiners, coordinators, teachers, whistle-blowers, or from IB-side checks on samples and response patterns.
2. The IB contacts the school and requires it to conduct an investigation and provide statements from all parties. **If a school fails to support the investigation, no grade is awarded to the student in the subjects concerned.**
3. The student is invited to submit a written statement. If they decline, the investigation proceeds and the school must confirm in writing that the opportunity was declined.
4. Where the IB notifies a school of an intended investigation, the school **may request removal of the piece of work from that session**. The student then receives no grade for it but may complete the subject in a future session, with entirely new work.
5. Cases go to an internal panel of experienced IB Education Office staff at the Global Centre in Cardiff, subject to approval by the **Academic Honesty Subcommittee**, which includes external members: teachers, integrity experts, university admissions staff and senior examiners.
6. Where evidence is inconclusive, subject-matter experts are consulted and the balance of probabilities applies.

[OFFICIAL] **The IB may investigate after results are issued.** If misconduct is then established, the grade may be withdrawn, which may withdraw the diploma. Students are expected to return certificates and new documentation is issued.

[OFFICIAL] The IB may also refuse to mark or moderate a submission where a student has acted irresponsibly or unethically in connection with it, or submitted inappropriate material unrelated to the assessment content.

[DERIVED] There is no statute of limitations that a student can rely on. The record is durable.

---', '', false, 44);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.1', 'EXTENDED ESSAY', '6. THE CORE', '**Critical currency note.** There are two live models. Establish which applies before answering anything.

- **Legacy model:** sessions up to and including **November 2026**. 34 marks, five criteria A to E, three-entry RPPF.
- **Current model:** first assessment **May 2027**. 30 marks, five criteria A to E with different names and weights, single reflective statement on the RPF, two formal pathways.

Primary source for the current model: *Extended essay guide, first assessment 2027*, International Baccalaureate, published February 2025.', 'extended essay EE 4000 words research question supervisor', false, 45);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.1.1', 'What is fixed across both models', '6. THE CORE', '[OFFICIAL]

- Compulsory for all diploma students; optional for course students.
- Independent research on a student-chosen topic, supervised by a qualified member of school staff.
- **Maximum 4,000 words.** No minimum is set.
- Approximately **40 hours** of student work.
- Supervision is recommended at three to five hours total, including **three mandatory reflection sessions**, the third of which is the **viva voce**, a short concluding interview after completion.
- Externally assessed. Combines with TOK for 0 to 3 diploma points.
- **A grade of D or higher is required for the award of the diploma.** An E is a failing condition.
- The subject must be chosen from the list published in the Assessment procedures for the session. It is normally one of the student''s six subjects, or a subject a course student has background in.
- Response language rules apply: a group 1 or group 2 EE must be written in the language of the subject; others must be in English, French or Spanish unless otherwise specified.
- **The EE must not duplicate any other work submitted for the diploma, including an IA.** This is a shared responsibility of student and supervisor.
- Secondary research, meaning a review of the literature available on the topic, is a requirement for **every** extended essay regardless of pathway or subject.

[OFFICIAL] Word count rules. **Examiners are instructed not to read or assess any material beyond 4,000 words.** The IB states plainly that essays over the limit are compromised across all criteria: knowledge demonstrated beyond the limit is treated as absent; analysis, discussion or evaluation beyond the limit is treated as though the point was never made. E-upload facilitates automatic recognition of the cut-off point.

**Excluded from the word count** [OFFICIAL]: contents page, maps, charts, diagrams, annotated illustrations, tables, equations, formulae and calculations, citations and references (parenthetical or numbered), footnotes and endnotes, bibliography, appendices. **Included**: introduction, body, conclusion, and all quotations.

[DERIVED] The abstract was removed under the current assessment model. Including one is not penalised but is not counted and serves no purpose.

[STRATEGY] Because the cut-off is a hard stop and the conclusion is where evaluation marks concentrate, an essay that runs long loses precisely the material that scores highest. Target 3,900 to 4,000. Do not cross. Equally, an essay well under roughly 3,500 words usually signals insufficient depth to sustain the argument, even where every sentence present is good.', '', false, 46);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.1.2', 'Current model: pathways (first assessment 2027)', '6. THE CORE', '[OFFICIAL] Students choose one of two pathways.

**Subject-focused pathway.** Research using the knowledge, concepts, theories, perspectives or methods of **one** DP subject. Strongly recommended that the student is already studying that subject.

**Interdisciplinary pathway.** Integrating knowledge, concepts, theories, perspectives or methods from **two** DP subjects, so that the elements work together to research the topic. This replaces the former World Studies essay.

[OFFICIAL] Restrictions and mechanics of the interdisciplinary pathway:

- **Environmental systems and societies and Literature and performance may not be used in the interdisciplinary pathway.** They are classified as cross-disciplinary and may only be used subject-focused. The stated reason is preventing over-complexity.
- The registration must place the essay in one of **five prescribed frameworks**: power/equality/justice; culture/identity/expression; movement/time/space; evidence/measurement/innovation; sustainability/development/change.
- **The connection to the framework is not directly assessed.** The frameworks exist to guide inquiry and to help the IB coordinate assessment. A topic need not connect to every word in a framework, and the same topic can sit in a different framework depending on the emphasis of the research question.
- **The balance between the two subjects does not need to be even.** It depends on the nature of the topic and the emphasis of the research question.
- The essay must demonstrate clearly that **integration of the two subjects specifically enabled an effective response to the research question**.
- It is strongly recommended that the student is studying at least one of the two subjects.
- Integration is described as something that develops through the process rather than a starting point. A student may begin by incorporating approaches from both subjects and gradually synthesise them.

[STRATEGY] The single test for whether a question is genuinely interdisciplinary: **if one subject alone could answer it, it is not interdisciplinary yet.** An essay that uses subject B only as background context for a subject A analysis will read as a subject-focused essay with decoration, and will lose marks in criteria A, B and D where integration is what is being appraised.', '', false, 47);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.1.3', 'Current model: criteria (30 marks, first assessment 2027)', '6. THE CORE', '[OFFICIAL] Marks and strands, with what each rewards paraphrased.

| Criterion | Marks | Strands | What it rewards |
| --- | --- | --- | --- |
| **A: Framework for the essay** | 6 | Research question; research methods; structure | A specific, focused question that is genuinely a question; explained suitability of the research methods and their connection to the subject''s methodology; visible application of those methods; structure following the conventions of academic writing in the chosen subject(s). |
| **B: Knowledge and understanding** | 6 | Knowledge; understanding of terminology; understanding of concepts | Research findings applied thoughtfully to build knowledge of the subject matter, relevant to the question and supporting the argument; accurate and consistent subject terminology; correct use of the subject''s key concepts. |
| **C: Analysis and line of argument** | 6 | Analysis; line of argument | Breaking the topic down to establish findings, each supported by evidence from the research; a reasoned thread with explicit signposting linking research question, findings and conclusions. |
| **D: Discussion and evaluation** | **8** | Discussion; evaluation | A considered and balanced review of the significance of the findings across a range of factors or perspectives, with conclusions supported by evidence; appraisal of the research materials, weighing strengths and limitations, including awareness of the stated or implied positions of the writers used. |
| **E: Reflection** | 4 | Evaluative; growth | Consideration of the value of the experience to the student as a learner, with explicit examples of transferring learned skills to other contexts; reflection on how changed perspectives affected decision-making and how the insights may shape future thinking. |
| **Total** | **30** | | |

[DERIVED] **Criterion D is now the heaviest single criterion at 8 marks, roughly 27 percent of the total.** The centre of gravity of the EE has moved from presentation and mechanics to evaluation. The old Presentation criterion is gone as a standalone; structure has moved inside criterion A.

[OFFICIAL] Criterion E is assessed from the **reflective statement on the RPF**, a single statement of no more than 500 words informed by all three reflection sessions and submitted after the viva voce.', '', false, 48);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.1.4', 'Legacy model: criteria (34 marks, to November 2026)', '6. THE CORE', '[OFFICIAL] Criterion A Focus and method, 6. Criterion B Knowledge and understanding, 6. Criterion C Critical thinking, **12**. Criterion D Presentation, 4. Criterion E Engagement, 6. Total 34.

[OFFICIAL] Criterion E is assessed from the **RPPF (Reflections on planning and progress form)**, which carries **three** student reflections totalling a maximum of 500 words plus supervisor comments. The examiner applies criterion E at the end, after reading the essay, considering the RPPF.

[UNCERTAIN] Legacy grade bands, stable across recent sessions but formally set per session: A 27 to 34, B 21 to 26, C 14 to 20, D 7 to 13, E 0 to 6.

[DERIVED] Under the legacy model, criterion C alone is 12 of 34 marks, over a third. The old model and the new model therefore point in the same strategic direction: **the marks are in thinking, not in reporting.** A student who writes clearly and accurately but paraphrases sources will score reasonably on B and poorly on the heaviest criterion.', '', false, 49);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.1.5', 'Research question design', '6. THE CORE', '[OFFICIAL] The guide''s own requirements. A research question should:

- be clearly stated and focused;
- remain open to amendment if the research moves;
- invite critical examination of the topic in terms of the knowledge, concepts, theories, perspectives or methods of the subject(s);
- encourage analysis, evaluation and synthesis rather than description, unsupported generalisation or value judgment;
- be answerable comfortably within 4,000 words.

[OFFICIAL] The guide names specific failure patterns to avoid:

- **Double-barrelled questions** combining more than one question, which almost always make the scope too broad.
- Questions liable to produce a descriptive essay.
- Questions leading the reader to a self-evident answer, which leave no room to construct a non-obvious argument.

[OFFICIAL] The guide recommends higher-order phrasings that engage deeper thinking: "how significant", "how successful", "to what extent", "what if".

[STRATEGY] The most reliable diagnostic to give a student: **if you can answer your research question in one sentence before doing the research, the question is wrong.** The second: if early investigation shows the sources are not there, change the question or the topic. The guide explicitly instructs flexibility on this point, and students who persist with an unsupportable question lose marks in criterion A and then everywhere downstream.', '', false, 50);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.1.6', 'Reflection and the RPF/RPPF', '6. THE CORE', '[OFFICIAL] Three reflection sessions are mandatory. The third is the viva voce, a short concluding interview after the essay is complete. The **researcher''s reflection space (RRS)** is a planning and progress tool the student maintains throughout, in whatever medium suits them, and is the raw material the formal reflections draw on.

[OFFICIAL] Reflection is assessed for evaluative quality and evidence of growth, not for procedural description of what the student did.

[STRATEGY] What separates a full-mark reflection from a low one, consistently reported in examiner commentary:

- **Procedural narration scores low.** "I met my supervisor, then I read three articles, then I wrote the introduction" is a log, not a reflection.
- **Specific decisions with reasons score high.** Explain why this topic, why these specific primary or secondary sources, why the question changed at a particular point.
- **Setbacks are an asset, not a confession.** Describing a method that failed, what was learned, and what would be done differently is exactly what the criterion rewards.
- **Transfer must be explicit.** The criterion asks for skills transferred to other contexts. Name the skill and name the other context.
- **Write the reflections at the time, not at the end.** Reflections composed in the week before submission produce generic statements that examiners recognise immediately, and they suppress the criterion score and therefore the core points.

[OFFICIAL] The RPPF (legacy) is used by the examiner to assess criterion E. The TOK equivalent, the TK/PPF, is **not** referred to when determining the essay mark; it is authenticity evidence. **These two forms work differently and should not be conflated.**', '', false, 51);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.1.7', 'Subject-specific EE guidance worth knowing', '6. THE CORE', 'Drawn from the *Extended essay guide, first assessment 2027*, subject-specific section.

**Language A** [OFFICIAL]:

- Must be based on one or more clearly defined texts: a single literary or language text, a comparison of more than one, or a comparison of a literary and a language text.
- In a comparative essay, **at least one primary text must have been originally written in the language the essay is registered in**. Others may be in translation.
- **The essay may not be based on a text studied in the course.** It may be based on a different text by an author studied.
- A student may not submit a Language A essay in the language of their Language B subject.
- A social, political or philosophical issue may be the topic, but the focus must be literary analysis of how the text treats it. **The text must not be used as documentary evidence for the issue.**
- Texts must have sufficient literary merit and complexity. Recently published works may lack critical literature; some young adult fiction may lack the depth for detailed analysis.
- Applying a generic or theoretical convention to a text is described as self-limiting. The guide''s own example of a weak topic is a Hero''s Journey reading of Harry Potter.
- If the text is a film, the focus must be on the screenplay, its delivery and its effect.
- **Biographical, historical, psychological and sociological topics are to be avoided**, as they pull away from literary analysis into narrative or description.
- Literary analysis has two components: identify an element in the text, then explain its significance or effect. Identification alone is not analysis. The guide frames the second step as answering "so what?".

**Interdisciplinary essays** [OFFICIAL]: the guide instructs students to read the subject-specific criteria guidance for **both** subjects, plus the generic guidance, and to be aware of the structural conventions of both.

**Removed restrictions in the current model** [OFFICIAL]: the time-based rules in History, Economics and Global politics have been removed, and the prescriptive category system for Language A and Language B (categories 1, 2, 3) has been removed and reframed as possible approaches.', '', false, 52);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.1.8', 'EE: moving from a B to an A', '6. THE CORE', '[STRATEGY] In order of leverage:

1. **Make every section answer the research question explicitly.** The commonest structural failure is a middle section that is interesting and irrelevant. Examiners assess against the question.
2. **Convert description into evaluation.** Under both models the heaviest criterion rewards weighing, not reporting. Every source used should be appraised, not just cited: who wrote it, from what position, with what limitations for this question.
3. **Signpost the line of argument.** The guide is explicit that connecting the parts is the author''s job, not the reader''s. Beginnings and ends of sections should be marked so the reader can see where the argument came from and where it leads.
4. **Do not summarise the critics.** Engaging critically with secondary sources scores; presenting them without engagement does not. An essay that repeats established critical views will not score well.
5. **Write the reflections honestly and early.** Criterion E is 4 marks of 30, and it is assessed from a document the examiner reads separately from the essay. A strong essay with a weak reflective statement is a common and entirely avoidable loss.
6. **Respect the word count as a design constraint, not a rule to test.**', '', false, 53);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.2', 'THEORY OF KNOWLEDGE', '6. THE CORE', 'Current guide: first teaching 2020, **first assessment 2022**. No replacement announced.', 'theory of knowledge TOK essay exhibition prescribed title objects', false, 54);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.2.1', 'Structure', '6. THE CORE', '[OFFICIAL] Two assessed tasks.

| Task | Assessment | Marks | Weight | Word limit |
| --- | --- | --- | --- | --- |
| **TOK essay** on a prescribed title | External | 10 | Two-thirds | 1,600 words |
| **TOK exhibition** | Internal, externally moderated | 10 | One-third | 950 words |

[DERIVED] The essay is counted twice in the aggregation, giving a total out of 30. The essay is therefore worth exactly twice the exhibition.

[OFFICIAL] The course covers a core theme (knowledge and the knower), optional themes (knowledge and technology, politics, language, religion, indigenous societies), and areas of knowledge (the arts, natural sciences, human sciences, history, mathematics).

[OFFICIAL] By design, **the exhibition is rooted in the core and optional themes; the essay emphasises areas of knowledge.** The exhibition is designed to be completed during the first year of the DP.', '', false, 55);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.2.2', 'The essay', '6. THE CORE', '[OFFICIAL]

- A formal, sustained piece of writing responding to **one of six prescribed titles** released by the IB for each session, roughly six months before the submission deadline.
- **The wording of the title may not be changed.**
- Maximum **1,600 words**, including quotations in the main body. Excludes acknowledgments, references (footnotes, endnotes or in-text) and bibliography.
- Examiners stop reading at 1,600 words.
- Assessed against a **single global assessment instrument**, not separate criteria. Five performance levels, holistic descriptors, marked out of 10. The driving question is whether the student provides a clear, coherent and critical exploration of the essay title.
- **Three formal recorded interactions with the teacher are required**, recorded on the **TK/PPF (TOK essay planning and progress form)**. The form is authenticity and support evidence. **Examiners do not refer to it when determining the mark.**

[STRATEGY] The essay''s characteristic failure modes and their fixes:

- **Writing about the topic rather than about knowledge.** The title is a second-order question about how knowledge is produced, justified and limited. An essay that becomes a discussion of climate science or of a historical event has left the subject.
- **Generic examples.** Examples that could have been written by anyone score poorly. Specific, dated, named examples from the student''s own subjects are the strongest currency in the essay.
- **No counterclaim.** The instrument rewards awareness of different perspectives. A one-sided essay caps.
- **Two areas of knowledge, handled properly, beats four handled shallowly.** Breadth without depth reads as coverage.
- **Title choice is a large fraction of the outcome.** Experienced TOK teachers routinely describe title selection as half the work. Choose the title where the student already has real, specific examples, not the title that sounds most interesting.
- **Do not use AI-generated examples.** They are recognisable, overused and generic, which is precisely what the instrument punishes, before any integrity question arises.', '', false, 56);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.2.3', 'The exhibition', '6. THE CORE', '[OFFICIAL]

- The student selects **one of 35 prescribed IA prompts**. The wording may not be changed. **The prompts are the same for every session.**
- The student selects **three objects**, or images of objects, each grounded in a specific real-world context.
- The student produces a single file containing the prompt, images of the three objects, and a commentary on each that identifies the object, explains its specific real-world context, justifies its inclusion, and explains its link to the prompt, with citations and references.
- Maximum **950 words** total across all three commentaries. Excludes text contained on or within the objects themselves, and acknowledgments, references and bibliography. Examiners stop reading at 950 words and assess only what precedes it. Extended footnotes and appendices are not appropriate.
- Assessed as a single whole against one instrument, out of 10.
- **The exhibition is an individual task. Group work is not permitted.** Students in the same class may use the same prompt but **may not use any of the same objects.**
- **If the exhibition is not based on one of the prescribed prompts, it is awarded zero.**
- Approximately 8 hours of teaching and preparation time.

[STRATEGY] What separates a top-band exhibition:

- **Objects must be specific, not categories.** "A newspaper" is a category. A named front page of a named paper on a named date, that the student has a personal connection to, is an object. Specificity is the largest single differentiator.
- **Three objects making the same point is one object repeated.** Each should open a different angle on the prompt.
- **Description is not analysis.** Every sentence should be tested: is this telling the reader what the object is, or is this revealing something about knowledge? Keep the second kind.
- **Use TOK concepts precisely.** Evidence, bias, certainty, interpretation, perspective, justification. Used accurately they show the moderator the student understands how knowledge works.
- **Pick objects first, then the prompt they illuminate**, rather than picking a prompt and hunting for objects to fit it.
- **Moderators see patterns.** Generic, widely circulated objects weaken the authenticity of the commentary.', '', false, 57);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.2.4', 'TOK grade and its diploma consequence', '6. THE CORE', '[OFFICIAL] The combined marks produce an A to E grade, which enters the core matrix (Section 2.2). **An E in TOK is a failing condition regardless of the student''s total points.**

[DERIVED] TOK is the most commonly under-resourced component in the diploma relative to its consequence. It carries the same failing-condition power as the EE while typically receiving far less student attention. For a student who is at risk, TOK is often the cheapest intervention available.', '', false, 58);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.3', 'CREATIVITY, ACTIVITY, SERVICE', '6. THE CORE', '[OFFICIAL] CAS is not formally assessed and contributes no points, but **authenticated completion is required for the award of the diploma**.', 'CAS creativity activity service reflections experiences project', false, 59);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.3.1', 'Requirements', '6. THE CORE', '[OFFICIAL]

- Three strands: **creativity** (arts and other experiences involving creative thinking), **activity** (physical exertion contributing to a healthy lifestyle), **service** (unpaid and voluntary exchange with a learning benefit for the student).
- CAS runs alongside academic study for a **minimum of 18 months**, ideally with regular, typically weekly, engagement, with a reasonable balance across the three strands.
- At least **one CAS project of at least one month''s duration**, which may draw on one or more strands.
- Students reflect at significant moments and maintain a **CAS portfolio**. **The portfolio is not formally assessed.** It is the evidence base.
- Using evidence from the portfolio, students must demonstrate achievement of the **seven CAS learning outcomes** to the CAS coordinator''s satisfaction. **All seven must be present.**
- Students must take part in a variety of experiences, some of which are self-initiated.
- CAS experiences must be distinct from work submitted for academic assessment.

[OFFICIAL] The seven learning outcomes, in the IB''s framing:

1. Identify own strengths and develop areas for growth.
2. Demonstrate that challenges have been undertaken, developing new skills in the process.
3. Demonstrate how to initiate and plan a CAS experience.
4. Show commitment to and perseverance in CAS experiences.
5. Demonstrate the skills and recognise the benefits of working collaboratively.
6. Demonstrate engagement with issues of global significance.
7. Recognise and consider the ethics of choices and actions.

[OFFICIAL] **The IB removed the fixed 150-hour guideline from the CAS requirements.** There is no IB-mandated hour count. Individual schools set their own expectations. [DERIVED] Therefore any answer that states "you need 150 hours" is wrong as an IB rule and may be right as a school rule. The system should always attribute hour targets to the school.

[UNCERTAIN] Most schools conduct three CAS interviews: initial, midpoint and final. This is common practice, not an IB requirement in the form usually described. Confirm with the coordinator.', '', false, 60);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '6.3.2', 'How CAS actually fails students', '6. THE CORE', '[DERIVED] The IB does not review individual portfolios. **The CAS coordinator verifies completion and certifies it to the IB. That single certification is the gate between a student and the diploma.**

[STRATEGY] The failure patterns:

- **Gaps in learning outcomes rather than gaps in effort.** A student with a very full portfolio can still be missing outcome 3 (initiating and planning) or outcome 6 (global significance) because everything they did was organised by someone else or was purely local. This is discovered at verification, in the final term, when it is expensive to fix.
- **One activity repeated for eighteen months.** Variety across strands and contexts, with visible progression, is what the outcomes ask for.
- **Reflection as diary.** The IB distinguishes description from reflection. Frequent short reflections beat rare polished ones, and they beat a single retrospective document written at the end.
- **Leaving it to year two.** The 18-month requirement is structural. It cannot be compressed.

[STRATEGY] Practical advice worth giving early: audit reflections against all seven outcomes at the end of year one. Any gap is trivially fixable then and painful in the final term.

---', '', false, 61);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.1', 'Why the IA is the highest-leverage component in the diploma', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', '[DERIVED] Four structural reasons, all of which follow from official rules:

1. **It is the only major component the student controls in advance.** Deadlines are known months ahead, the criteria are published, and the work can be revised before submission.
2. **The criteria are published in full.** Unlike an examination markscheme, the student can read exactly what is being rewarded before producing the work.
3. **The mark-per-scaled-point ratio is usually favourable.** See the Biology worked example in 3.2: one IA mark can be worth roughly 1.7 marks on a large-raw-total paper.
4. **Non-submission is a diploma failure, not a partial loss.** See 3.13.

[STRATEGY] The counterweight: moderation (3.6) means the teacher''s mark is provisional, so a student should optimise for *criterion visibility to a fast external reader*, not for impressing their own teacher.', 'internal assessment IA why important leverage marks', false, 62);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.2', 'Master table', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', 'Verify the guide currency (Section 1.2) before using any row.

| Subject | Task | Word limit | Raw marks | Weight SL | Weight HL | Criteria |
| --- | --- | --- | --- | --- | --- | --- |
| **Biology / Chemistry / Physics** (2025 guide) | Scientific investigation | 3,000 | 24 | 20% | 20% | Research design 6, Data analysis 6, Conclusion 6, Evaluation 6 |
| **ESS** (2026 guide) | Individual investigation | 3,000 | 30 | 25% | 20% | Includes a new strategy/tensions criterion |
| **Mathematics AA / AI** (2021 guide) | Mathematical exploration | No word limit; 12 to 20 pages recommended | 20 | 20% | 20% | Presentation 4, Mathematical communication 4, Personal engagement 3, Reflection 3, Use of mathematics 6 |
| **History** (2017 guide) | Historical investigation | 2,200 | 25 | 25% | 20% | Identification and evaluation of sources 6, Investigation 15, Reflection 4 |
| **Economics** (2022 guide) | Portfolio of three commentaries | 800 per commentary | 45 (14 x 3, plus 3 portfolio marks) | 30% | 20% | Five criteria per commentary |
| **Business management** (2024 guide) | Business research project | 1,800 | 25 | 30% | 20% | Common SL/HL, includes key concept integration and supporting documents |
| **Geography** | Fieldwork written report | 2,500 | 25 | 25% | 20% | Six criteria A to F |
| **Psychology** (2027 guide) | Research proposal (hypothetical) | 2,200 | [UNCERTAIN] | | | New task; replaces the experimental report |
| **Computer science** (2027 guide) | Computational solution plus video | Documentation-based | 30 | 30% | 20% | Problem specification, planning, system overview, product, plus one further criterion |
| **Language A** (2021 guide) | Individual oral | 15 minutes | 40 | 30% | 20% | Four criteria A to D |
| **Language B** (2020 guide) | Individual oral | Timed | 30 | 25% | 20% | Language, message, conceptual understanding (varies by level) |
| **Design technology** (2027 guide) | Design project, 50 hours | | | | | Unified SL/HL criteria |

[UNCERTAIN] Marks and weights for the 2027-first-assessment subjects are still settling in public sources. Verify against the subject guide before stating them.', 'IA internal assessment word limit marks weighting criteria every subject table', false, 63);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.3', 'Sciences: the scientific investigation', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', 'Source: Biology, Chemistry and Physics guides, first assessment 2025. The IA requirement is **identical across the three subjects**.

[OFFICIAL]

- One open-ended task in which the student gathers and analyses data to answer their own formulated research question.
- Written report, **maximum 3,000 words**. Excluded from the count: data tables, equations, calculations, citations, bibliography, headers, graphs, appendices.
- 10 hours. 20% of the final grade at both levels. Marked out of 24 and externally moderated.
- **Four criteria, 6 marks each, weighted 25% each: Research design, Data analysis, Conclusion, Evaluation.**
- **Personal engagement and Communication were removed as standalone criteria** in this guide.
- Inquiry in small groups is permitted; methodologies may be shared where appropriate, **but the final report must be individual and each student''s data and analysis must be their own.**
- The research question need not go beyond the understandings in the guide, but the investigation must have sufficient extent and depth for all descriptors to be accessible.
- Criteria are applied independently using a **best-fit** model. The highest descriptors do not imply faultless performance.
- Teachers should not assume any particular distribution of marks and should not think in terms of pass or fail, only in terms of the appropriate descriptor.

[DERIVED] **Conclusion and Evaluation together are 12 of 24 marks, 50 percent.** The centre of gravity in the current sciences IA is scientific reasoning and critical reflection, not procedure. Students trained on the pre-2025 model systematically under-invest here.

**What each criterion actually rewards** [OFFICIAL, paraphrased]:

- **Research design.** How effectively the report communicates the purpose and the practice of the methodology. A research question with context should reference the dependent and independent variables (or two correlated variables), concisely describe the system the question sits inside, and include directly relevant background theory. Methodology must be described so it could be repeated.
- **Data analysis.** Whether raw data has been recorded, processed and presented in a way that allows a conclusion to be drawn, including appropriate treatment of uncertainties.
- **Conclusion.** Whether the student answers their own research question with regard to their analysis and the accepted scientific context. A conclusion that is *fully consistent* requires interpretation of the processed data **including associated uncertainties**. Justification through relevant comparison to the accepted scientific context is required, and cited published material must be traceable.
- **Evaluation.** Whether the report evaluates the methodology and suggests improvements. The top band requires explaining the **relative impact of specific methodological weaknesses or limitations**, and realistic improvements that address those specific issues.

[STRATEGY] Where science IA marks are actually lost:

- **Generic evaluation.** Comments that could apply to any experiment ("human error", "more trials") score at the bottom of the criterion. The descriptor requires specificity and relative impact: which weakness mattered most, and why.
- **Conclusion that ignores uncertainty.** Reporting a trend without reference to error bars, uncertainty ranges or the confidence the data actually supports fails the "fully consistent" requirement.
- **Conclusion with no scientific context.** A conclusion that does not compare to published values or accepted theory cannot reach the top band.
- **Under-powered data.** [STRATEGY, widely used teacher heuristic, not an IB rule] Examiners commonly expect at least five levels of the independent variable with at least five trials each. This is a norm, not a requirement; the requirement is sufficient data to support the analysis.
- **Word count spent on background.** With 3,000 words and half the marks in conclusion and evaluation, an introduction that consumes a third of the budget is a structural error.

[OFFICIAL] The use of generative AI to write the report is prohibited by the authentication requirement. Individually, each student must formulate the research question, establish the methodology, identify variables, collect and analyse the data, and draw conclusions.', 'biology chemistry physics science IA scientific investigation lab practical research question data analysis conclusion evaluation', false, 64);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.4', 'Mathematics: the exploration', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', 'Source: Mathematics AA and AI guides, first assessment 2021. Applies to all sessions through May 2028.

[OFFICIAL]

- A written exploration of a mathematical topic of the student''s choosing.
- **20 marks, 20% of the final grade at both levels.** 10 to 15 hours of student work. Recommended 12 to 20 pages.
- **No word limit.** Length is not the standard; focus is.
- Five criteria: **Presentation 4, Mathematical communication 4, Personal engagement 3, Reflection 3, Use of mathematics 6.**
- Personal engagement must be evidenced **in the student''s work**. A teacher''s comment that the student was engaged is not sufficient.
- SL and HL have slightly different Use of mathematics descriptors; HL expects greater sophistication, rigour and fewer errors.
- Any idea, method or content not the student''s own must be cited **at the point of use**. A bibliography alone is insufficient and may lead to a misconduct finding.

[OFFICIAL] The distinction between criteria A and B, which students routinely confuse: **Presentation** concerns the overall organisation and coherence of the exploration. **Mathematical communication** concerns the appropriateness of the mathematics, notation, terminology and forms of representation. An exploration can be well organised with inappropriate mathematics, or use excellent diagrams and technology while lacking a clear aim.

[STRATEGY] The three highest-value insights for the maths IA:

1. **Personal engagement measures engagement with the mathematics, not enthusiasm for the topic.** Stating "I have always been interested in..." earns nothing. What earns marks is evidence of interacting with the mathematics: exploring unfamiliar mathematics, testing predictions, examining a detail a textbook would skip, playing with alternative formulations to understand them, presenting ideas in the student''s own way. A technically flawless exploration that follows a textbook method mechanically will be held down by this criterion alone.
2. **Reflection is not description.** Describing what was done is not reflection, however carefully written. Reflection reviews, analyses and evaluates the exploration, and can appear throughout rather than only in a conclusion.
3. **The topic choice can cap the score before a line is written.** A topic that permits only routine application of a standard method cannot reach the top band of Use of mathematics, which rewards mathematics commensurate with the level, correct, and thoroughly understood.

[STRATEGY] The mechanical failures that recur in examiner reports: correlation explorations that compute a coefficient with no justification of its use, then chain on a chi-squared or t-test with no rationale; confusing correlation with causation; and modelling explorations that fit a curve without interrogating the model''s assumptions or limitations.

[DERIVED] Arithmetic worth showing a student: the IA is 20 marks scaled to 20 percent, so **one IA mark equals one percent of the subject total.** A student targeting a solid 6 at roughly 65 percent overall needs about 13 out of 20 on the exploration just to stay on pace.', 'maths mathematics AA AI exploration IA pages personal engagement', false, 65);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.5', 'History: the historical investigation', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', 'Source: History guide, first assessment 2017. Applies through May 2027; the new guide is first assessed May 2028.

[OFFICIAL]

- **2,200 words maximum.** Bibliography and clear referencing must be included but are outside the count.
- 25 marks. 25% at SL, 20% at HL. Same requirements at both levels. Approximately 20 hours.
- Any historical topic, provided it is not on the syllabus content the student is being examined on in a way that creates duplication.
- Three sections:

| Section | Criterion | Marks |
| --- | --- | --- |
| 1. Identification and evaluation of sources | A | 6 |
| 2. Investigation | B | **15** |
| 3. Reflection | C | 4 |

[OFFICIAL] What each rewards, paraphrased:

- **Criterion A.** An appropriate question for investigation, clearly stated. Appropriate sources identified and selected, with explanation of their relevance to the investigation. Analysis and evaluation of **two** sources with detailed reference to their value and limitations. The bottom band describes sources rather than analysing or evaluating them.
- **Criterion B.** Critical analysis clearly focused on the question, with evidence, and with different perspectives referenced. A reasoned conclusion consistent with the evidence.
- **Criterion C.** Reflection on what undertaking the investigation revealed about the methods used by, and the challenges facing, historians, with a clear and explicit relationship to the rest of the investigation.

[STRATEGY] Where History IA marks are lost:

- **OPVL as a checklist.** Listing origin, purpose, value and limitation as four labelled sentences scores in the middle. The top band requires **explaining how the origin and purpose produce the value and the limitation for this specific question.** The link is the mark, not the list.
- **Very low word counts are self-punishing.** With 15 of 25 marks in section 2, an investigation that runs short cannot demonstrate sustained analysis.
- **Reflection written as a general essay on historiography.** Criterion C requires the reflection to arise from what the student''s own investigation revealed. Generic philosophy of history scores low.
- **No historiography in section 2.** Referencing different historians'' interpretations is what moves the investigation from narrative to analysis.
- **A conclusion that summarises rather than judges.** Section 2 must reach a definitive, evidenced judgment.

[STRATEGY] Source selection is the highest-leverage early decision. Academic sources, and specifically peer-reviewed articles accessible through JSTOR and similar databases, give a student material to evaluate. Popular websites give them nothing to say in criterion A.', 'history IA historical investigation sources evaluation 2200', false, 66);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.6', 'Economics: the portfolio', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', 'Source: Economics guide, first assessment 2022.

[OFFICIAL]

- A portfolio of **three commentaries**, each based on a different published news media article.
- **Maximum 800 words each.** Moderators consider only content within the limit.
- Each commentary must cover a **different unit** of the syllabus: microeconomics, macroeconomics, the global economy.
- Each must use a **different key concept** from the nine: scarcity, choice, efficiency, equity, economic well-being, sustainability, change, interdependence, intervention. **One concept per commentary, no repeats.**
- Each article must come from a **different source**.
- Each article must be **of current interest**, published no more than one year before the commentary was written.
- The full article must be included in the portfolio, with the relevant sections highlighted, along with title, source, date and syllabus unit.
- Each commentary is marked out of **14 across five criteria**. Three further portfolio-level marks are available: one for covering different units, one for different sources, one for currency. **Total 45.**
- 30% at SL, 20% at HL. Approximately 20 hours.
- Marked using a **best-fit** model; it is not necessary to meet every point in a descriptor.

[STRATEGY] Where Economics IA marks go:

- **Diagrams are load-bearing.** An accurately drawn, correctly labelled, and explicitly **referred-to** diagram is the backbone of the analysis criterion. A diagram that appears and is not discussed earns little.
- **One-sided evaluation caps the mark.** "This policy is good because" without stakeholders, downsides, short versus long run, or assumptions is the commonest evaluation failure.
- **Summarising the article is not application.** The task is to apply theory to the specific situation, not to report what the article says. Two or three sentences of summary maximum.
- **The key concept must be integrated, not announced.** Naming the concept in the introduction and never returning to it forfeits the concept marks.
- **Quotations from the article count towards the 800 words.** Use them sparingly.
- **Pacing beats cramming.** One commentary per term across the two years produces materially better portfolios than three written in one month, because each benefits from feedback on the previous one.

[DERIVED] At SL the Economics IA is 30 percent of the subject. That makes it the single highest-weighted IA of the major group 3 subjects and the strongest available buffer against a difficult paper.', 'economics IA portfolio commentaries articles diagrams', false, 67);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.7', 'Business management: the research project', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', 'Source: Business management guide, first assessment 2024. **Common to SL and HL.**

[OFFICIAL]

- A research project applying business management tools and theories to a **real** organisational issue or problem, through a conceptual lens.
- **Maximum 1,800 words.** Excluded: acknowledgments, contents page, tables of statistical data, diagrams and figures, equations and calculations, supporting documents, citations, references in footnotes or endnotes, bibliography. Only the first 1,800 words are marked.
- **25 marks.** 30% at SL, 20% at HL. Approximately 20 hours.
- The issue must be real, not hypothetical. The project must refer directly to a **single organisation**, though it may consider industry-wide issues affecting it.
- The research question may be forward looking or backward looking.
- **Exactly one of four key concepts** must be used as the analytical lens: change, creativity, ethics, or sustainability.
- **Three to five supporting documents** must be attached, from which the majority of the information is drawn.
- Primary and/or secondary research, selected for suitability, depth and breadth.

[UNCERTAIN] Criterion structure widely reported as including integration of the key concept (5 marks), supporting documents (4 marks), and selection and application of tools and theories (4 marks), with the remainder across analysis, conclusions and structure. Verify against the guide before quoting marks.

[STRATEGY] The two decisive early choices are the organisation and the concept. An organisation with thin public information starves the supporting documents criterion. A concept chosen for convenience rather than fit produces a lens that is mentioned and then abandoned, which is where most of the concept marks are lost. Supporting documents should be recent, varied in perspective, reliable and detailed enough to sustain analysis.', 'business management IA research project supporting documents', false, 68);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.8', 'Geography: the fieldwork report', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', '[OFFICIAL]

- Written report based on a fieldwork question derived from any suitable syllabus topic, involving collection and analysis of primary data at a local scale.
- **Maximum 2,500 words.** Excluded: title page, acknowledgments, contents page, titles and subtitles, references, footnotes up to 15 words each, map legends and keys, labels of 10 words or fewer, tables of statistical or numerical data or category names, calculations, and appendices containing only raw data and calculations.
- **25 marks**, six criteria A to F. 25% at SL, 20% at HL. Approximately 20 hours.
- Where the work exceeds the limit, teachers and moderators are advised to stop reading, which particularly damages the later criteria.
- Appendices should contain only representative examples of materials used, not every completed questionnaire, and not secondary information.

[STRATEGY] Recurring moderator complaints: no clear geographic theory linking the question to the syllabus; convenience sampling used without acknowledging it; figures without titles, units or scales; graphs presented without interpretation; and evaluation that ignores obvious confounds such as weather, time of day or sample size. The fix for the last three is mechanical and cheap.', 'geography IA fieldwork report data collection', false, 69);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.9', 'Language A: the individual oral', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', 'Source: Language A guides, first assessment 2021 (both Literature and Language and literature).

[OFFICIAL]

- 15 minutes: a 10-minute student presentation followed by 5 minutes of teacher questions.
- Internally assessed, externally moderated. 40 marks. **30% at SL, 20% at HL.**
- In Language and literature the student prepares **two extracts, one literary and one non-literary**, connected by a **global issue** of their choosing. In Literature, two literary works are used.
- Four criteria A to D: knowledge/understanding/interpretation; analysis and evaluation; focus and organisation; language.

[OFFICIAL] A global issue must meet three tests: significance on a wide scale, transnational reach, and impact felt in everyday local contexts.

[OFFICIAL] Component separation rules, which students breach every year: the works used for the individual oral **may not be used** for the HL essay, and **may not be used** for paper 2.

[OFFICIAL] The HL essay is 1,200 to 1,500 words on one work or body of work studied in the course, excluding works used for the IO and works chosen for paper 2. It is 20% at HL and externally assessed.

[STRATEGY] The commonest individual oral failures: a global issue defined so broadly it does nothing to organise the analysis; feature-spotting (naming devices without effect); unbalanced treatment of the two extracts; and reciting a memorised script, which produces flat delivery and, if drawn from unreferenced sources, has produced level 3a misconduct penalties (see 5.5).', 'language A literature english IA individual oral extract global issue', false, 70);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.10', 'Language B: the individual oral', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', 'Source: Language B guide, first assessment 2020.

[OFFICIAL]

- **SL:** presentation and discussion based on a **visual stimulus** linked to one of the five prescribed themes, followed by general conversation on one or more themes.
- **HL:** presentation and discussion based on an **extract from one of the two literary works studied**, followed by discussion on one or more themes.
- Assessment criteria are more demanding at HL.
- The five prescribed themes are common to both levels: identities; experiences; human ingenuity; social organisation; sharing the planet.
- Paper 1 assesses productive writing against three criteria: **language, message, conceptual understanding**. SL writes 250 to 400 words; HL writes 450 to 600. Paper 2 has separate listening and reading sections.

[OFFICIAL] A critical and frequently missed rule: **a response that ignores context, purpose and audience may receive zero for the message and conceptual understanding criteria even if it scores highly on language.** Choosing an inappropriate text type is therefore not a small error; it is potentially a two-thirds loss on paper 1.

[OFFICIAL] Language acquisition is the stated exception to the general position that IB assessment does not reward spelling and grammar. Marks are awarded for sentence structure, and **the use of language-improvement software is not permitted in these subjects.**', 'language B spanish french IA individual oral stimulus', false, 71);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.11', 'ESS: the individual investigation', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', 'Source: ESS guide, first assessment 2026.

[OFFICIAL]

- **3,000 words maximum**, increased from 2,250 under the old guide.
- **30 raw marks**, common criteria at SL and HL. **25% at SL, 20% at HL.** Ten hours.
- Collaboration in small groups is now permitted, with shared methodologies allowed provided variables differ and each student''s data is unique.
- A new criterion addresses **strategy and the tensions inherent in environmental issues**, requiring a nuanced understanding of the issue or context investigated.

[STRATEGY] The strategy criterion is the differentiator and the part with no legacy exemplars. It requires the student to show how different perspectives affect the outcome of a strategy, which is an ESS-specific demand that does not appear in the pure science IAs. Students who treat the ESS IA as a Biology IA with an environmental topic will lose that criterion entirely.', 'ESS environmental systems societies IA individual investigation', false, 72);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '7.12', 'Computer science and Psychology under the 2027 guides', '7. INTERNAL ASSESSMENT: MASTER REFERENCE', '[OFFICIAL] **Computer science.** Paper 3 removed. Two themes. The IA is a **35-hour computational solution**, marked out of **30 across five criteria**, requiring a **video submission alongside the documentation**. 30% at SL, 20% at HL, same criteria at both levels. Marks are whole numbers only and awarded on a best-fit basis. There is also a 10-hour collaborative sciences project. The 2027 guide does not require a named client.

[STRATEGY] The scoping error that dominates: whole-school timetabling systems and full library management systems do not fit in 35 hours. Four of the five criteria assess process; only one assesses the finished product, with the video as primary evidence of functionality. A modest system, fully documented and demonstrably working, outscores an ambitious system that does not run.

[OFFICIAL] **Psychology.** The experimental report is replaced by a **research proposal on a hypothetical study**, up to **2,200 words**. The course is restructured around concepts (bias, causality, change, measurement, perspective, responsibility), content (biological, cognitive and sociocultural approaches) and four contexts (human development, health and well-being, human relationships, learning and cognition), with class practicals embedded. HL extensions investigate culture, motivation and technology across the four contexts. Paper 3 (HL) is source-based with quantitative and qualitative data.

[STRATEGY] The strategic implication of the redesign is that memorised studies are no longer the unit of currency. Studies become evidence for reasoning about a context. Students revising by memorising study lists will underperform against a paper designed to test transfer.

---', 'computer science psychology IA 2027 new guide', false, 73);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '8.1', 'The general answer', '8. WHAT SEPARATES A 5 FROM A 7', '[OFFICIAL] The IB''s own group grade descriptors describe grade 7 performance in group 3 as demonstrating conceptual awareness, insight, and knowledge and understanding evident in critical thinking; fully developed, logically structured answers illustrated with appropriate examples; precise subject-specific terminology; familiarity with the literature of the subject; the ability to analyse and evaluate evidence and synthesise knowledge and concepts; awareness of alternative viewpoints and of subjective and ideological bias; and the ability to reach reasonable, if tentative, conclusions.

[DERIVED] Unpacking that against what students actually produce, the 5 to 7 gap almost never lies in content coverage. It lies in five specific capacities:

1. **Performing the command term rather than the topic.** A 5 knows the material and answers the subject. A 7 performs the operation the verb demands.
2. **Evaluating rather than listing.** A 5 presents strengths and limitations. A 7 weighs them against stated criteria and reaches a judgment that follows from the weighing.
3. **Specificity of evidence.** A 5 uses correct but generic examples. A 7 uses precise, named, dated examples deployed to make a point rather than to demonstrate knowledge.
4. **Acknowledging alternative positions.** The descriptor explicitly names awareness of alternative points of view and of bias. A 5 argues one side well. A 7 shows it has considered the other and explains why it is less convincing.
5. **Tentativeness handled well.** The descriptor asks for reasonable, tentative conclusions. A 5 either overclaims or refuses to conclude. A 7 states a position and marks its limits.

[STRATEGY] The practical translation: at grade 5 a student is demonstrating that they know things. At grade 7 they are using what they know to do something to a question. The revision behaviour that produces the second is attempting real questions under time and then reviewing against the markscheme, not re-reading notes.', 'get a 7 improve grade difference between 5 and 7 top marks', false, 74);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '8.2', 'Where marks are recovered per subject', '8. WHAT SEPARATES A 5 FROM A 7', '[STRATEGY] These are the highest-yield interventions per subject, drawn from examiner report patterns and the criteria weightings established above.

**Sciences (Bio/Chem/Phys).** The single largest recoverable block is the IA evaluation and conclusion (12 of 24 IA marks). In examinations: data-based questions reward precise reading of axes, units and error bars, and are more predictable than recall questions. Extended response questions reward structured, connected explanation rather than volume. In Biology from May 2027, Paper 2 Section B no longer awards a separate structure mark; the mark is redistributed across the subparts.

**Mathematics.** In examinations, method marks are recoverable even when the final answer is wrong, and are routinely forfeited by students who show no working. On calculator papers, the answer alone can score zero on a multi-mark question. In the exploration, the recoverable block is personal engagement and reflection, 6 of 20 marks, which are lost by students who write technically correct but mechanical work.

**English A.** The recoverable block is analysis of authorial choices rather than plot. In paper 1, the chain is technique to effect to purpose; naming a technique without effect scores at the bottom. In paper 2, structure by point of comparison and refer to both works in every paragraph. Quotations do not need to be memorised for paper 2. In the HL essay, one sharp line of inquiry sustained without drift beats a broad survey.

**Language B.** The recoverable block is text type and register on paper 1, because getting these wrong can zero two of three criteria regardless of language quality. In the individual oral, spontaneity in the discussion phase is worth more than a polished memorised presentation.

**History.** The recoverable block is historiography and explicit judgment. Paper 1 rewards precise source handling, including the value and limitation of origin and purpose. Paper 2 and paper 3 essays that narrate rather than argue cap in the middle bands regardless of factual density. Every essay needs a thesis in the introduction that uses the question''s own command term.

**Economics.** The recoverable block is evaluation and diagrams. Diagrams must be accurate, labelled and explicitly referenced in the prose. Evaluation must consider stakeholders, short versus long run, assumptions and the reliability of the underlying theory.

**Business management.** The recoverable block is the conceptual lens and the application of tools to the specific organisation rather than generic description of the tool.

**Psychology.** The recoverable block is critical thinking in extended responses: alternative explanations, methodological evaluation of the studies cited, and areas of uncertainty. Under the 2027 guide this shifts further toward applying content to unfamiliar contexts.

**Geography.** The recoverable block is interpretation of figures and place-specific detail. Named, located, dated case studies with real numbers separate the top bands from generic answers.

**TOK.** The recoverable block is specificity of examples and the presence of a genuine counterclaim.

**Extended essay.** The recoverable block is criterion D (or legacy criterion C): evaluation of sources and of the essay''s own effectiveness.

---', 'recover marks per subject where to improve', false, 75);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '9', 'GRADE DESCRIPTORS: WHAT EACH NUMBER MEANS', null, '[OFFICIAL] The IB publishes group-level grade descriptors. They are the reference senior examiners use when setting boundaries (Section 3.3) and the reference teachers use when forming predicted grades (Section 3.7). Summarised and paraphrased:

| Grade | Label | Character of the performance |
| --- | --- | --- |
| **7** | Excellent | Conceptual awareness and insight; fully developed, logically structured answers with appropriate examples; precise terminology; analysis, evaluation and synthesis; awareness of alternative viewpoints and bias; reasoned, appropriately tentative conclusions. |
| **6** | Very good | Thorough knowledge and understanding with detailed development; sound analysis and evaluation; generally accurate terminology; minor errors that do not undermine the response. |
| **5** | Good | Sound knowledge and understanding; competent but less consistent analysis; conclusions present but less well supported; some imprecision. |
| **4** | Satisfactory | Adequate knowledge with limited development; largely descriptive with occasional analysis; conclusions asserted rather than argued. |
| **3** | Mediocre | Limited knowledge; descriptive throughout; frequent inaccuracy; little structure. |
| **2** | Poor | Very limited knowledge; superficial or inaccurate; little relevant response to the question. |
| **1** | Very poor | Minimal evidence of knowledge or understanding. |
| **N** | No grade | No grade awarded; see 3.13. |

[DERIVED] Two things students should take from this table. First, the boundary between 4 and 5 is largely the boundary between description and analysis. The boundary between 6 and 7 is largely the boundary between analysis and evaluation with awareness of alternatives. Second, **the descriptors are subject-group specific and the official versions should be read for the student''s own group.** Teachers use them to build predictions, which makes them the most useful single document a student can read early in year one.

---', 'grade descriptor what does a 5 mean 6 7 4 3', false, 76);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '10', 'LEGITIMATE HIGH-LEVEL STRATEGY', null, 'Everything in this section is [STRATEGY] unless labelled otherwise, and everything is bounded by Section 5. Nothing here involves misrepresenting authorship, evading authentication, fabricating data, or accessing material a student is not entitled to. These are consequences of understanding the assessment system, which the IB itself makes public specifically so that students can use it.', '', false, 77);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '10.1', 'Arithmetic strategy: know where your marks live', '10. LEGITIMATE HIGH-LEVEL STRATEGY', '1. **Compute the scaling factor for every component of every subject.** Take the component''s weighting divided by its raw mark total. That number is the scaled value of one raw mark. Spend revision time where the number is highest and the marks are most gettable. [DERIVED from 3.2.]
2. **Identify your SL-heavy IAs.** Economics SL (30%), Business management SL (30%), Computer science SL (30%), Language A SL individual oral (30%), History SL (25%), Geography SL (25%), ESS SL (25%). At SL these components are a quarter to a third of the subject and are entirely within the student''s control months in advance.
3. **Compute the core points arbitrage.** Look at the matrix in 2.2, find the pair the student is currently heading for, and identify which single grade movement changes the points. Improving the already-stronger component frequently changes nothing.
4. **Check the failing conditions before optimising the total.** A student adding points to a subject they are already passing while carrying a projected HL total of 11 is optimising the wrong number entirely (see 2.3).', '', false, 78);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '10.2', 'Structural strategy: the components you control', '10. LEGITIMATE HIGH-LEVEL STRATEGY', '1. **Front-load everything that can be finished early.** The TOK exhibition is designed for year one. Economics commentaries are designed to be paced one per term. Both are routinely deferred and both are cheap when done on time.
2. **Treat the IA calendar as the real calendar.** Examination revision is compressible. Coursework deadlines are not, and a rushed IA damages a component worth 20 to 30 percent of a subject.
3. **Never miss a submission.** Non-submission produces an N and withholds the diploma. There is no scenario in which submitting weak work is worse than submitting nothing. [DERIVED from 3.13 and 2.3.]
4. **Build the audit trail as you go.** Drafts, dated files, a source log, notes. It costs nothing, satisfies authentication, and protects against any authenticity challenge. [OFFICIAL recommendation, see 5.6.]
5. **Read the criteria before writing, not after.** The EE guide explicitly instructs that students should have access to the assessment criteria from the beginning and should use them to inform the research and writing. The same logic applies to every IA.', '', false, 79);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '10.3', 'Component-level strategy', '10. LEGITIMATE HIGH-LEVEL STRATEGY', '1. **Write to the criterion, visibly.** Moderators and examiners work at speed against criteria. Signpost. Use headings where the subject permits. Make each criterion''s evidence findable.
2. **Respect every word limit as a cut-off, not a penalty.** Aim just under. Never over. Put the evaluation and conclusion where the examiner will definitely reach them.
3. **Front-load the highest-weighted criterion.** In the current EE that is discussion and evaluation. In the current sciences IA it is conclusion and evaluation. In History it is the investigation. Allocate the word budget accordingly, in advance.
4. **Use the exclusions.** Word counts across the IB exclude tables, diagrams, calculations, references and appendices. Data and figures placed correctly cost no words. This is not a loophole; it is the published structure of the count. It is, however, subject to a hard limit: material placed in extended footnotes or appendices to smuggle argument past the count is explicitly described as inappropriate in TOK, and would be treated as part of the essay.
5. **Answer every question, and answer the verb.** Blank answers score zero with certainty. A partial answer that performs the correct operation frequently picks up the lower band.
6. **Show working in quantitative subjects even when a calculator is permitted.** Method marks are the largest recoverable block in maths and physics papers.', '', false, 80);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '10.4', 'Time triage under pressure', '10. LEGITIMATE HIGH-LEVEL STRATEGY', 'Decision rules, in priority order, for a student who cannot do everything:

1. **Protect against failing conditions first.** Anything at risk of an N, an E in TOK or the EE, a grade 1, or an unmet CAS outcome takes absolute priority over improving a grade elsewhere. A withheld diploma is a categorical loss; a 6 instead of a 7 is not.
2. **Then protect the HL 12 and SL 9 thresholds.** These are structural minimums that a good total does not rescue.
3. **Then the highest scaled value per hour.** Usually an unfinished or weak IA in a subject where the IA weight is 25 to 30 percent.
4. **Then the cheapest core point.** The weaker of TOK and EE, if a single grade movement changes the matrix outcome.
5. **Then examination technique in the subject with the largest gap between knowledge and marks.** Usually diagnosable as command term failure rather than content gaps.
6. **Last, content coverage in a subject already performing near target.**

[STRATEGY] The most common misallocation observed in strong students is spending the final term pushing a subject from 6 to 7 while a core component sits at a C and CAS outcomes are unevidenced.', 'running out of time triage panic behind deadline priorities', false, 81);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '10.5', 'Subject selection strategy', '10. LEGITIMATE HIGH-LEVEL STRATEGY', '1. **Group 6 is the only substitutable group.** Choosing an arts subject forecloses a second science, humanity or language. That is a real strategic cost for students targeting science or social science degrees.
2. **ESS satisfies group 3 or group 4, not both.** It is the standard route for a student who needs to free capacity for three demanding HLs. From 2026 it is available at HL as well.
3. **Three HLs done well beats four HLs done adequately**, unless a target programme explicitly requires four. HL and SL are worth the same maximum points. The HL 12-point threshold is calculated on the three highest HL grades where four are taken, which slightly reduces the risk of a fourth HL but does not remove the workload.
4. **Check university requirements before finalising, not after.** [OFFICIAL] The IB explicitly does not guarantee recognition and places responsibility for verifying entry requirements on students and guardians (General regulations, article 5).
5. **Language B at HL is often a stronger play than a second Language A** for a student who wants the linguistic credential without doubling the literary essay load. The bilingual diploma requires only a grade 3, so a student close to that route should check whether the cross-language subject path is available at their school.', '', false, 82);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '10.6', 'The EE and TOK strategic layer', '10. LEGITIMATE HIGH-LEVEL STRATEGY', '1. **Choose the EE subject for source availability and personal traction, not prestige.** The EE grade is worth the same regardless of subject.
2. **Do not use an EE topic that overlaps an IA.** Duplication carries a level 3a penalty **in both subjects** (see 5.4 and the documented precedent in 5.5).
3. **Choose the TOK title where the specific examples already exist.** Title selection is the largest single determinant of the essay''s ceiling.
4. **Do the exhibition properly in year one.** It is a third of the TOK grade, designed to be done early, and is frequently rushed by students who then need TOK to carry a core point.
5. **Write the reflections at the time.** Criterion E in the EE is assessed from a separate document that is easy to do well and commonly done badly.', '', false, 83);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '10.7', 'The results-day layer', '10. LEGITIMATE HIGH-LEVEL STRATEGY', '1. **Diagnose which condition failed before choosing an instrument.** A subject retake cannot repair a core failure.
2. **The coordinator can see how close each grade was to a boundary.** That information is the single best predictor of whether a remark is worth the fee and the risk, and it is free.
3. **A remark can go down and the result is final.** Consent is required for that reason. Use it where one grade determines something real.
4. **The three-session limit no longer exists** (see 3.12). A retake is available in any future session at any school willing to accept the candidate.
5. **Highest grade counts.** [OFFICIAL] A retake cannot lower the diploma outcome for that subject, because the highest grade contributes.

---', '', false, 84);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '11', 'THE DIPLOMA RISK ENGINE', null, 'Logic the system should run whenever a student asks "could this affect my diploma?".

**Step 1. Is a component at risk of non-submission?**
If yes: this is a diploma-level risk. Non-submission produces an N in that subject, which triggers failing condition 3. Escalate immediately and tell the student to speak to their coordinator today.

**Step 2. Is TOK or the EE at risk of an E?**
If yes: diploma-level risk regardless of points. An E in either is a failing condition.

**Step 3. Is CAS complete?**
Check: 18 months of engagement, all three strands, at least one project of at least one month, all seven learning outcomes evidenced, portfolio maintained, coordinator satisfied. Unmet CAS withholds the diploma with no points remedy.

**Step 4. Run the numeric conditions.**
- Total points at least 24.
- No grade 1 anywhere.
- No more than two grade 2s.
- No more than three grades of 3 or below.
- HL total at least 12 (three highest if four HLs).
- SL total at least 9, or at least 5 where only two SLs are taken.

**Step 5. Is there any live academic integrity issue?**
A level 3a penalty produces an N. A Final Award Committee misconduct penalty is itself a failing condition.

**Step 6. If a condition fails, name the instrument.**
- Core failure: TOK or EE resubmission in a future session; CAS completion through the school.
- Numeric failure: subject retake, or enquiry upon results if a grade is genuinely borderline.
- Integrity failure: appeal only where process was not followed or new evidence exists.

[STRATEGY] Tone guidance for the system. This is a high-anxiety question. The correct response is precise and calm: identify which specific condition is at risk, state the instrument, and route the student to their coordinator. Do not soften the arithmetic and do not catastrophise a condition that is not actually at risk.

---', 'risk failing diploma at risk conditions danger', false, 85);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '12', 'MYTHS AND CORRECTIONS', null, '| Common claim | Status | Correction |
| --- | --- | --- |
| "You get three exam sessions to complete the diploma." | **False** | The IB has removed the three-session restriction, applicable to all past, current and future students. |
| "CAS requires 150 hours." | **False as an IB rule** | The IB removed the fixed hour guideline. Schools set their own expectations. |
| "24 points means you pass." | **False** | 24 points is one of ten conditions. Students above 24 are denied the diploma every session on HL totals, grade caps, core grades or CAS. |
| "HL subjects are worth more points." | **False** | Both levels max at 7. The distinction operates through the separate HL and SL minimums. |
| "A 4 is always a pass." | **Misleading** | The IB does not define a universal pass mark per subject. Diploma award depends on the full condition set. |
| "Grade boundaries rise when the cohort does well." | **Misleading** | Boundaries respond primarily to paper difficulty. A lower boundary usually signals a harder paper. |
| "Going over the word count costs a few marks." | **False** | Examiners stop reading. The material is treated as absent, which damages every criterion that depends on it. |
| "A bibliography covers me." | **False** | Citation must appear at the point of use. A correct bibliography with uncited body text has produced level 3a penalties. |
| "The IB bans AI." | **False** | The IB explicitly declines to ban AI tools. It requires disclosure and citation including the prompt and date, and prohibits their use for language improvement in language acquisition. |
| "AI detectors will catch me / can''t catch me." | **Both misleading** | The IB declines to rely on detection. Enforcement runs through teacher authentication: development over time, ability to explain the work, and quality consistent with the student. |
| "My teacher''s IA mark is my IA mark." | **False** | It is provisional until moderation, which can move the whole cohort in either direction. |
| "I can appeal my predicted grade to the IB." | **False** | The IB does not set predicted grades and has no mechanism to change them. Any review is internal to the school and only before submission. |
| "I can request a remark myself." | **False** | Only the school may submit an enquiry upon results, and written consent is required because grades can fall. |
| "Maths changes in 2027." | **False** | First teaching August 2027, first assessment May 2029. |
| "The TOK presentation." | **Obsolete** | Replaced by the exhibition, first assessment 2022. |
| "World Studies EE." | **Obsolete from 2027** | Replaced by the interdisciplinary pathway with five prescribed frameworks. |
| "Digital exams are harder." | **False** | The IB states the questions, structure and standards are the same, with boundaries set so format does not advantage either group. |
| "A retake could lower my diploma score." | **False** | The highest grade for the subject contributes. |
| "Talking about the paper afterwards is fine once everyone in my school has finished." | **False** | The rule is a full 24 hours after the examination ends, because of other time zones. Level 3a penalties have been applied for general comments. |

---', 'myth false rumour untrue misconception', false, 86);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '13', 'SOURCE REGISTER', null, 'Every source used to compile this document, with version or date, so that claims can be re-verified and the document updated.', '', false, 87);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '13.1', 'Primary IB sources (highest authority)', '13. SOURCE REGISTER', '| Source | Version / date | Used for |
| --- | --- | --- |
| *Diploma Programme Assessment procedures 2026*, incorporating **General regulations: Diploma Programme** (Part B) | Published 2025, for May and November 2026 sessions | Articles 1 to 17: registration, response language, core requirements, copyright, results, enquiry upon results, Final Award Committee, access, adverse circumstances, misconduct, appeals |
| *Academic integrity policy* | Published October 2019, updated March 2023; Appendix 6 on AI added March 2023 | Section 5 in full: definitions, penalty matrices, precedents, AI guidance, maladministration |
| *Extended essay guide, first assessment 2027* | Published February 2025 | Section 6.1: pathways, frameworks, criteria, research question guidance, Language A subject guidance |
| *IB assessment principles and practices: A guide to assessment for teachers and coordinators* | Current version, ibo.org | Section 3: scaling, boundaries, standardisation, seeding, tolerance, moderation, at-risk re-marking, EUR categories |
| *Conduct of examinations booklet 2026* | For 2026 sessions | Section 3.15: reading time, announcements, late arrivals, supervision, secure materials |
| *Use of calculators in IB DP examinations 2026*, version 1.0 | For 2026 sessions | Calculator rules |
| ibo.org, "Read curriculum updates" | Last updated 24 March 2026 | Section 1.2 first assessment table |
| ibo.org, subject update pages (History, Psychology, Computer science, ESS, Mathematics AA, Mathematics AI, Visual arts, Design technology, Language B, Language ab initio, Dance) | 2025 to 2026 | Curriculum review dates and change summaries |
| ibo.org, "Retaking examinations" and Assessment FAQ | Accessed 2026 | Section 3.12: removal of the three-session limit, highest grade rule |
| ibo.org, "Diploma programme assessment" / "Understanding IB assessment" | Accessed 2026 | Points structure, bilingual diploma |
| ibo.org, "Moderation" | Accessed 2026 | Moderation factor and purpose |
| ibo.org news release, "More than 209,000 IB students worldwide receive their DP and CP results" | 6 July 2026 | May 2026 session statistics, NECM |
| ibo.org, "Artificial intelligence (AI) in learning, teaching and assessment"; IB statement on ChatGPT | First published March 2023, updated March 2025 | AI position |
| IB Extended essay guide (legacy) word count provisions, ibpublishing.ibo.org | Legacy model | Section 6.1.1 word count consequences |
| IB *Examiner instructions 2026* (sciences and history sections) | For 2026 sessions | IA moderation mechanics, science IA marks and weight, history IA marks and weight |
| Group grade descriptors | In use from September 2015 / December 2017 editions | Section 9 |', '', false, 88);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '13.2', 'Secondary and school-published sources (used for corroboration)', '13. SOURCE REGISTER', 'Used where primary text was not directly retrievable, and flagged as [UNCERTAIN] in the body where corroboration was thin.

- IB school academic integrity and access policies published by IB World Schools (Scarborough College 2025 to 2027; La Paz School 2024 to 2025; Turner Fenton Peel Schools; Hwa Chong International; Windermere School v25.1; Riverview IB), used to corroborate policy wording and dates.
- School and teacher subject sites: tokresource.org, tok2022.net, teacherweaver.com (Inderkum TOK), ibgeographypods.org, drsielinski.com, ibmastery.com, ibchem.com, biologyforlife.com, geta7.com, englishcollaborative.com, libguides at West Sound Academy, International School of Beijing, International School of Zug and Luzern, American School of Madrid, Shekou International School.
- Publisher and platform summaries of guide changes: ManageBac, AssessPrep, Oxford University Press, Cambridge University Press, Pearson, Revision Village, InThinking.
- Results and statistics reporting: *Tes* (6 July 2026), WhichSchoolAdvisor (July 2026), School Management Plus, IB final statistical bulletin summaries for May 2025.
- Tutoring and revision providers, used only for corroboration of widely reported practice and never as sole authority for a rule: Lanterna, Clastify, RevisionDojo, Tutopiya, IB Innovators, Bespoke Learning, TutorChase, Hack Your Course, KIS Academics, TutorsPlus, MarkScheme, Studyib, IBretake, MyRevisionAgent.', '', false, 89);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '13.3', 'Known gaps in this version', '13. SOURCE REGISTER', 'Flagged so they can be closed in version 1.1:

1. **Access and inclusion policy** was not retrievable directly from ibo.org during compilation (bot protection). Section 3.11 relies on the General regulations summary plus school-published implementations. **Extra time percentages, the full arrangement list and the request deadline should be verified against the current policy before being stated as fact.**
2. **2027-first-assessment mark allocations** for Psychology, Design technology and Visual arts IAs are incomplete in public sources. Verify against the guides.
3. **Enquiry upon results fees and exact deadlines** are session-specific and were only available from secondary sources. Verify against the Assessment procedures for the relevant session.
4. **Full TOK assessment instrument level descriptors** are not reproduced here, deliberately, on copyright grounds. The system should describe what the instrument rewards, not quote it.
5. **The new History guide (first assessment 2028)** is summarised only at the level of structure. Detailed criteria were not available.
6. **CAS review status** is unannounced. Treat the current guide as live but re-check.
7. **Grade boundary data** is deliberately excluded. Boundaries are set per session and any published table is historical. The system should explain the mechanism rather than quote numbers.

---', '', false, 90);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '14', 'UPDATE PROTOCOL', null, '[STRATEGY] What to re-verify, and when, to keep this document trustworthy.

**Every year, in February.** The IB publishes new guides in February for August first teaching. Check the curriculum updates page and update Section 1.2.

**Every year, before the session.** The Assessment procedures, Conduct of examinations booklet and calculator policy are republished annually. Check Sections 3.15 and 3.11.

**Every year, in July and January.** Results statistics and the statistical bulletin. Update Section 2.6.

**On any IB policy announcement.** Academic integrity policy and AI guidance have moved twice since 2023 and are the most likely thing in this document to change. Section 5.6 is the highest-churn content here.

**Rolling.** The on-screen examination rollout expands by subject group each session. Section 1.4.

**Never stale-safe.** Grade boundaries, fees, deadlines. These should always be presented as session-specific and routed to the coordinator, never cached as facts.', '', false, 91);
insert into public.knowledge_sections (corpus, section, title, parent_title, body, keywords, always_include, ordinal)
values ('IB_DP', '14.1', 'Instructions to the system on uncertainty', '14. UPDATE PROTOCOL', 'When the system encounters an IB question it cannot answer from this document, the correct response is:

1. State what is known from this document, with its label.
2. State plainly what is not known.
3. Name the authoritative source: the subject guide, the Assessment procedures for the session, or the DP coordinator.
4. Do not guess. Do not fill the gap with plausible-sounding structure.

A student who is told "I do not have that; ask your coordinator" loses thirty seconds. A student who is told a confident wrong word limit loses marks.

---

*End of Albus IB Knowledge Base v1.0. Compiled August 2026. All IB assessment criteria described in this document are paraphrased, not reproduced. IB rubrics, guides and policy documents are the copyright of the International Baccalaureate Organization.*', '', true, 92);

